import { findPassage, passageLevels, type Passage, type PassageLevel } from "@/app/passages";
import type { StoryQuiz } from "@/app/stories";

/* The stories children get as their assignment: proper storybook tales,
   written to be enjoyed, in the spirit of the funny, warm, larger-than-life
   books children love: a narrator with a voice, characters with silly
   names, comic disasters, a twist, and a heart at the end. All original.

   Kept apart from the Guided Reading passages, which are short on purpose
   (they're timed read-alouds benchmarked by length). These grow with the
   reader: a few lines at Starter, a full short story by Year 6, with
   sentence length and vocabulary stepping up through the levels.

   The Lexile figures are estimates within each level's band. */

function A(
  id: string,
  title: string,
  emoji: string,
  lexile: number,
  text: string,
  question: string,
  options: [string, string][],
): Passage {
  const quiz: StoryQuiz = {
    question,
    options: options.map(([e, l]) => ({ emoji: e, label: l })),
    answer: 0,
  };
  return { id, title, emoji, lexile, text, quiz };
}

const STARTER: Passage[] = [
  A("as-st-01", "The Big Fat Hat", "🎩", 50, "Dad has a hat. It is a big, fat, red hat. Dad sat on the hat. Squash! The hat is flat. Dad is sad. Mum got the hat. Mum hit it. Pop! Up it got. It is big and fat. But a cat is in it! The cat had a nap in Dad's hat. Dad is not sad now. But the cat is not glad. “Get out, cat!”", "What was in Dad's hat?", [["🐱", "A cat"], ["🐟", "A fish"], ["🍎", "An apple"]]),
  A("as-st-02", "Pig Wants a Bath", "🐷", 50, "Pig is in the mud. Pig is not pink. Pig is a big mud blob! Mum Pig is cross. “Get in the tub, Pig!” Pig gets in the tub. Scrub, scrub, rub. Pig is pink! Pig is so pink. Then Pig hops out. Pig runs and runs and runs... back to the mud. Splat! “PIG!” yells Mum.", "Where does Pig run at the end?", [["🟤", "Back to the mud"], ["🛁", "To the tub"], ["🛏️", "To bed"]]),
  A("as-st-03", "Ten Hens in a Van", "🚐", 50, "Ten hens get in a van. Ten hens in a van is a lot of hens! The van is red. The hens sit and sit. Then a fox sees the van. “Yum,” said the fox. The fox gets in the van. Ten hens peck the fox. Peck, peck, peck! The fox jumps out. Run, fox, run! The hens are the boss of the van.", "Who pecked the fox?", [["🐔", "Ten hens"], ["🐶", "A dog"], ["🐱", "A cat"]]),
  A("as-st-04", "Gran Can Kick", "⚽", 50, "Gran is not big. Gran is not fast. Ben has a ball. “Can I kick it?” said Gran. Ben is not sure. Gran runs. Gran kicks. BAM! The ball zips up and up and up. It is a big, big kick! It hits a bus. The bus stops. Ben gasps. Gran is the best. Ben has a lot to learn.", "What did the ball hit?", [["🚌", "A bus"], ["☀️", "The sun"], ["🏠", "A house"]]),
  A("as-st-05", "The Bug in My Bed", "🐛", 50, "I get in bed. I hug my ted. But I am not on my own. A bug is in my bed! The bug has six legs. It sits on my leg. Tickle, tickle! I am not sad. I am not mad. I am giggling! The bug is fun. But Mum is not fun. “Bug! Out!” said Mum. Bye, bug.", "How many legs does the bug have?", [["6️⃣", "Six"], ["2️⃣", "Two"], ["🔟", "Ten"]]),
  A("as-st-06", "Kit and the Jam", "🍓", 50, "Kit the cat likes jam. Kit gets on the box. Kit gets on the tin. Kit gets up to the jam pot. Lick, lick, lick. Yum! Kit is a jam cat. Kit has jam on his lip. Kit has jam on his leg. Kit has jam on his tum. Mum sees Kit. Mum is not happy. Now Kit is in the bath. Not yum!", "What did Kit lick?", [["🍓", "Jam"], ["🥛", "Milk"], ["🐟", "Fish"]]),
  A("as-st-07", "Dad and the Big Dig", "⛏️", 50, "Dad digs a pit. Dig, dig, dig. The pit gets big. The pit gets bigger. Dad is in the pit. “Help!” said Dad. “I am stuck in the pit!” Sam gets a rope. Mum gets a rope. The dog gets a bun. Tug, tug, tug! Up pops Dad. Dad is a mud man! The dog eats the bun.", "Who got stuck in the pit?", [["👨", "Dad"], ["🐶", "The dog"], ["👩", "Mum"]]),
  A("as-st-08", "The Duck Who Did Not Quack", "🦆", 50, "A duck sat on a log. Ducks quack. That is the job. But this duck did not quack. This duck went MOO! The ducks got a fright. A frog fell in. A cow ran up. “Is that my mum?” said the cow. The duck went red. “Sorry,” said the duck. “I had a cold.”", "What did the duck say?", [["🐮", "Moo"], ["🦆", "Quack"], ["🐶", "Woof"]]),
  A("as-st-09", "The Hot Pot", "🍲", 50, "Mum has a big pot. In the pot is a lot of hot soup. Dad wants the soup. Sam wants the soup. The dog wants the soup. But the pot is too hot. So they wait. And wait. And wait. Then the pot is not hot. But the pot is... empty! Gran had it all. Gran has a big tum.", "Who had all the soup?", [["👵", "Gran"], ["🐶", "The dog"], ["👦", "Sam"]]),
  A("as-st-10", "Big Bad Bob", "🐻", 50, "Bob is a big bad bear. “I am big,” said Bob. “I am bad. I can ROAR!” Bob gets up on a rock. ROAR! Then a bird sits on Bob's nose. Tweet, tweet. Bob runs off! Bob hid in his den. Bob is big. Bob is bad. But Bob is not fond of birds.", "What made Bob run off?", [["🐦", "A bird"], ["🐍", "A snake"], ["🦁", "A lion"]]),
];

const YEAR1: Passage[] = [
  A("as-y1-01", "The Grumpiest Goat in the World", "🐐", 300, "Gertie was a goat. She was not just any goat. She was the grumpiest goat in the whole wide world. When the sun came out, Gertie said, “Too hot!” When the rain came down, Gertie said, “Too wet!” When the farmer sang, Gertie put her hooves over her ears. One day, a tiny lamb came to the farm. The lamb was so happy that it bounced. Boing! Boing! Boing! “Stop bouncing,” said Gertie. “It makes me dizzy.” But the lamb just bounced closer. Then it gave Gertie a big, woolly hug. Gertie went pink. Gertie went red. Then something very strange happened. The corner of her mouth went up. Just a tiny bit. The farmer dropped his bucket. The hens fell off their perch. Gertie the goat was smiling! It only lasted for one second. Then she said, “Too fluffy!” But we all saw it.", "Who made Gertie smile?", [["🐑", "A tiny lamb"], ["🐔", "A hen"], ["👨‍🌾", "The farmer"]]),
  A("as-y1-02", "Sir Snorebert", "🛡️", 330, "Sir Snorebert was the bravest knight in the land. Well, he would have been, if he could stay awake. Every time he got on his horse, he yawned. Every time he picked up his sword, he nodded off. Zzzzz. One day, a dragon flew over the castle. The king shook Sir Snorebert. “Wake up! A dragon!” Sir Snorebert opened one eye. Then he shut it again. And then he snored. It was the loudest snore anyone had ever heard. It rattled the windows. It shook the towers. It blew the king's crown right off his head! The dragon was so frightened that it flew all the way to the other side of the mountains. The king gave Sir Snorebert a gold medal. He did not see it. He was asleep.", "How did Sir Snorebert scare the dragon away?", [["😴", "With a loud snore"], ["⚔️", "With his sword"], ["🐴", "On his horse"]]),
  A("as-y1-03", "The Smelly Surprise", "🍈", 360, "Adam's Auntie Zaza loved durian more than anything in the world. One day, she brought home the biggest, spikiest durian Adam had ever seen. “Smell that!” she said, holding it under his nose. Adam smelled it. His eyes watered. His hair stood up. His socks curled. “It smells like a dinosaur's sock!” he gasped. Auntie Zaza just laughed and cracked it open. The smell rolled out of the kitchen. It rolled down the hall. It rolled out of the door and all the way down the street. The neighbours shut their windows. The cat moved house. Then Auntie Zaza gave Adam a tiny piece. It was soft. It was sweet. It was creamy like custard. Adam blinked. “Auntie,” he said slowly, “can I have another piece?” The cat is still not speaking to him.", "What did Adam think the durian smelled like?", [["🧦", "A dinosaur's sock"], ["🌹", "A rose"], ["🍞", "Fresh bread"]]),
  A("as-y1-04", "Mr Muddle's Magic Socks", "🧦", 380, "Mr Muddle bought a pair of socks from a very strange shop. They were purple with yellow spots. “These are magic socks,” said the shopkeeper, with a wink. Mr Muddle did not believe him. He put them on anyway. At once, his feet began to dance! They danced him out of the door. They danced him down the road. They danced him right into the middle of the town square. Tap, tap, twirl! Tap, tap, twirl! A crowd came to watch. People clapped. A dog joined in. Even the policeman did a little jig. By teatime, Mr Muddle was so tired that he could hardly stand. He took off the socks and put them in a drawer. Then he locked it. Twice. But every night, he can still hear them tapping.", "What did the magic socks make Mr Muddle do?", [["💃", "Dance"], ["🏃", "Run"], ["😴", "Sleep"]]),
  A("as-y1-05", "The Cat Who Thought She Was a Dog", "🐱", 400, "Mimi was a cat. Everybody knew she was a cat. She had whiskers. She had a long tail. She said miaow. Everybody knew she was a cat, except Mimi. Mimi thought she was a dog. She fetched sticks. She chased the postman. She tried to wag her tail, but it just swished. When the family went for a walk, Mimi trotted along on a lead. People stared. “Is that a cat on a lead?” they whispered. Mimi did not care. One day, a real dog came to live next door. His name was Bruno. Bruno looked at Mimi. Mimi looked at Bruno. Then Bruno curled up in a sunny window and purred. It turned out that Bruno thought he was a cat! They swapped jobs at once, and everyone was much happier.", "What did Bruno think he was?", [["🐱", "A cat"], ["🐶", "A dog"], ["🐟", "A fish"]]),
  A("as-y1-06", "Grandpa's Terrible Cooking", "🍳", 420, "Everyone loved Grandpa. But nobody loved his cooking. His porridge was lumpy. His soup was gloopy. His cakes were so hard that you could build a wall with them. One Sunday, Grandpa said, “Today, I will make a pizza!” Everyone gulped. He put on his apron. He put on the cheese. He put on the tomatoes. Then he put on some jam, some fish fingers and a whole banana. “A secret recipe,” he said. Into the oven it went. Out it came, smoking a little. Nobody wanted to try it first. So the dog did. The dog took one bite and asked for more! Grandpa was delighted. Now every Sunday, Grandpa makes Jam and Banana Fish Finger Pizza. The dog eats all of it. Everyone else has toast.", "Who liked Grandpa's pizza?", [["🐶", "The dog"], ["👨‍👩‍👧", "Everyone"], ["👵", "Granny"]]),
  A("as-y1-07", "The Tooth Fairy's Day Off", "🧚", 440, "Lily had lost a tooth. She put it under her pillow and went to sleep. But the Tooth Fairy had a cold. “Atchoo!” She could not fly. So she sent her little brother, Dennis. Dennis had never done the job before. He flew in through the window. He bumped into the lamp. He landed in the goldfish bowl. Splash! By the time he had dried himself off, he had forgotten what he came for. He looked under the pillow and found the tooth. “What a funny little stone,” he said. He took the tooth and left a sock. In the morning, Lily found the sock. She thought about it. Then she wrote a note: “Dear Tooth Fairy, I think there has been a mix-up.” The next night, there were two shiny coins, and a sorry note in very wobbly writing.", "What did Dennis leave under the pillow?", [["🧦", "A sock"], ["🪙", "A coin"], ["🍪", "A biscuit"]]),
  A("as-y1-08", "Sang Kancil and the Crocodiles", "🐊", 460, "Sang Kancil was a small mouse deer. He was not big, and he was not strong, but he was very, very clever. One hot day, Kancil wanted the sweet fruit on the other side of the river. But the river was full of hungry crocodiles. “Good morning, crocodiles!” called Kancil. “The King wants to know how many of you there are. Please line up across the river so that I can count you.” The crocodiles wanted to please the King. So they lined up, nose to tail, all the way across. Kancil hopped onto the first one. “One!” Then the next one. “Two!” Hop, hop, hop, all the way across. “Twenty-three!” he shouted from the other side. “And thank you for the bridge!” The crocodiles snapped their jaws, but it was too late. Kancil was already munching his fruit.", "How did Kancil cross the river?", [["🐊", "On the crocodiles' backs"], ["🛶", "In a boat"], ["🏊", "He swam"]]),
  A("as-y1-09", "The Burp That Saved the Day", "💨", 490, "Toby could do the biggest burps in the whole school. His teacher, Mrs Prim, did not like them one bit. “Toby! Manners!” she would say. One day, the class went on a trip to the zoo. Mrs Prim leaned over the wall to look at the hippos. Whoops! Her glasses fell off. They landed on a hippo's nose. The hippo opened its huge mouth. It was about to swallow them! Nobody knew what to do. Then Toby took a deep breath. He drank his whole fizzy drink. And he let out the biggest burp of his life. BUUURRRP! The hippo got such a shock that it sneezed. The glasses flew through the air and landed right on Mrs Prim's nose. Everyone cheered. Mrs Prim smiled. “Just this once, Toby,” she said. “Just this once.”", "What made the hippo sneeze?", [["💨", "Toby's burp"], ["🌸", "A flower"], ["🐒", "A monkey"]]),
  A("as-y1-10", "The Moon Wants a Holiday", "🌙", 520, "Every night, the Moon came out to shine. Every night, for millions of years. One night, she said, “I am tired. I want a holiday.” So she packed a little bag and floated down to the beach. She put on her sunglasses. She lay on a towel. She had an ice cream. It was lovely. But up in the sky, it was very, very dark. The owls bumped into trees. The cats fell off walls. The fishermen could not find their way home. A little girl called Nora looked up at the empty sky. Then she looked down at the beach. “Excuse me,” she said to the Moon. “We miss you.” The Moon felt a warm glow inside. She packed up her towel and floated back up. “Maybe just one holiday a month,” she said. And that is why, once a month, the Moon disappears.", "Who asked the Moon to come back?", [["👧", "Nora"], ["🦉", "An owl"], ["🐱", "A cat"]]),
];

const YEAR2: Passage[] = [
  A("as-y2-01", "The Day the Teacher Turned Into a Frog", "🐸", 480, "Mr Bunting was the strictest teacher at Puddleford Primary. He never smiled. He never laughed. He said “No talking!” about four hundred times a day. On Monday morning, Mr Bunting took a sip of his tea and made a face. Somebody had swapped his sugar for a strange green powder from the science cupboard. There was a puff of smoke. When it cleared, Mr Bunting was gone. In his chair sat a small, cross-looking frog wearing a tiny pair of glasses. “Ribbit,” said the frog, very sternly. The class stared. Then Priya giggled. Then everyone giggled. For one whole day, Class 2B did exactly as they pleased. They had crisps for breakfast. They painted the ceiling. They had a spelling test where every answer was “ribbit”. But by home time, they felt strange. The classroom was too quiet. Nobody said “No talking!” Nobody checked their homework. Priya picked up the frog and gave it a little kiss on the head, just to say sorry. Puff! There stood Mr Bunting, with paint on his shoes and pond weed in his hair. He looked at the ceiling. He looked at the class. And then, for the first time ever, he laughed.", "What did Priya do to turn the frog back?", [["💋", "Gave it a kiss"], ["🍵", "Gave it tea"], ["📚", "Read it a book"]]),
  A("as-y2-02", "Nenek's Secret Recipe", "🍛", 500, "Every Saturday, Nenek made the best nasi lemak in the whole of Johor. People queued all the way down the street for it. The rice was fluffy. The sambal was so spicy that it made your ears tingle. And there was a secret ingredient that nobody knew. Aiman wanted to know the secret more than anything. He hid behind the curtain and watched her cook. Nothing. He peeked through the kitchen window. Nothing. He even hid in the rice sack, but he sneezed and got caught. At last, Nenek sat him down. “Do you really want to know?” she asked. Aiman nodded so hard that his head nearly fell off. Nenek leaned closer. “The secret,” she whispered, “is that I make it for people I love.” Aiman frowned. “That's not an ingredient!” “Isn't it?” said Nenek, smiling. The next Saturday, Aiman helped her cook. He stirred the sambal. He folded the banana leaves. He made a parcel for his teacher, for his best friend and for the grumpy man at number nine. The grumpy man took a bite, and for the first time anyone could remember, he smiled. Aiman grinned. Now he knew the secret worked.", "What was Nenek's secret ingredient?", [["❤️", "Cooking for people she loved"], ["🌶️", "Extra chilli"], ["🍯", "Honey"]]),
  A("as-y2-03", "Kevin the Rock", "🪨", 510, "Everyone in Class Two had a pet. Jack had a puppy. Mei had a parrot that could say “Pass the biscuits.” Oscar had a hamster called Professor Fluffington. Ruby had a rock. It was grey. It was round. It was called Kevin. “Kevin can't do anything,” laughed Jack. “He can't fetch. He can't talk. He can't even run on a wheel.” Ruby lifted her chin. “Kevin is very good at sitting still,” she said. On Pet Day, the animals came to school. It was chaos. The puppy chased the hamster. The hamster escaped into the piano. The parrot shouted “Pass the biscuits!” until the head teacher came in. In all the noise, a gust of wind blew the classroom door wide open. All the homework flew off the desks and swirled around the room like snow. Everyone screamed. Then Ruby calmly picked up Kevin and placed him on top of the pile. The papers stopped flying at once. The class went quiet. Kevin had saved the day. At the end of the week, Kevin won Pet of the Year. He did not say anything. But Ruby was sure he looked very pleased.", "How did Kevin save the day?", [["📄", "He held the papers down"], ["🎵", "He played the piano"], ["🐶", "He caught the puppy"]]),
  A("as-y2-04", "Captain Cutlass and the Very Small Ship", "🏴‍☠️", 530, "Captain Cutlass was the most terrifying pirate on the seven seas. He had a black beard, a red coat and a voice like a thunderstorm. There was just one problem. His ship was tiny. It was so tiny that it was really a bathtub with a sail. “Arrr!” he would roar at passing ships. “Give me your treasure!” The other sailors would lean over the side and laugh so hard that they nearly fell overboard. One stormy night, a huge wave crashed over a great big ship called the Golden Goose. Its sailors tumbled into the sea. They could not swim, and the water was cold and black. Then a little light came bobbing over the waves. It was Captain Cutlass in his bathtub. He pulled them out, one by one, until there were seventeen soggy sailors squashed into his tiny ship. Someone's elbow was in his ear. But he rowed them safely home. The next morning, the sailors gave him a gift. It was a big new ship with a golden flag. Captain Cutlass looked at it for a long time. Then he gave it back. “Too big,” he said. “Now, who wants a ride in the bath?”", "What was Captain Cutlass's ship really?", [["🛁", "A bathtub"], ["🚢", "A huge ship"], ["🛶", "A canoe"]]),
  A("as-y2-05", "The Girl Who Never Stopped Asking Why", "❓", 550, "Ella asked questions. Lots of them. “Why is the sky blue? Why do cats purr? Why do we have toes?” From morning till night, the questions poured out of her like water from a tap. Her mum got dizzy. Her dad hid in the shed. Her teacher, Miss Lark, started wearing earmuffs. One day, the whole town lost power. The lights went out. The fridges stopped humming. The traffic lights went dark. All the grown-ups stood in the street, scratching their heads. “Why has the power gone?” asked Ella. Nobody knew. So she went to find out. She followed the wires down the street. She followed them past the park. She followed them all the way up the hill to the power station. There she found the answer. A family of squirrels had built a nest right on top of the big switch. Ella gently moved the nest to a tree. Click! Every light in town flicked back on. That evening, the mayor gave Ella a shiny medal. “How did you know what to do?” he asked. Ella grinned. “I asked why,” she said. “And then I went to find out.”", "What had turned off the power?", [["🐿️", "A squirrels' nest"], ["⛈️", "A storm"], ["🐘", "An elephant"]]),
  A("as-y2-06", "Uncle Bernard's Bouncing Bed", "🛏️", 560, "Uncle Bernard bought a new bed. It was big. It was bouncy. It was, according to the label, “the bounciest bed ever made”. Uncle Bernard did not read labels. That night, he took a running jump into bed, the way he always did. BOING! He shot straight up through the ceiling. BOING! He bounced off the roof. He sailed over the chimney in his pyjamas, holding his teddy bear. The neighbours were woken by a loud “Wheeeeee!” Mrs Patel looked out of her window just in time to see Uncle Bernard fly past, waving. “Lovely evening!” he called. He bounced over the church. He bounced over the school. He bounced right across the river and back again. At last, he came down where he had started, straight through the hole in the roof and onto his bed. Boing... boing... boing. He fell fast asleep. The next morning, he told everyone he had had a wonderful dream about flying. The neighbours did not say anything. They just looked at the hole in his roof, and at the pigeon still sitting on his head.", "Where did Uncle Bernard land at the end?", [["🛏️", "Back on his bed"], ["🌊", "In the river"], ["⛪", "On the church"]]),
  A("as-y2-07", "The Shy Dragon", "🐉", 580, "In a cave above the village lived a dragon called Fizz. Fizz was very large and very green, and she was very, very shy. Whenever anyone looked at her, she blushed bright pink. And whenever she blushed, little puffs of smoke came out of her ears. The villagers were terrified. “A dragon!” they screamed whenever they saw the smoke. They locked their doors and hid under their beds. Fizz did not want to scare anyone. She just wanted a friend. One freezing winter, the snow fell for days and days. The villagers ran out of firewood. Their houses grew colder and colder. A small boy called Tomas was so cold that he climbed all the way up the mountain to find help. He found Fizz. Fizz blushed. Puff, puff went the smoke. “Please,” said Tomas, shivering. “We're freezing.” Fizz took a deep breath. Very gently, she breathed warm air over the village. The snow melted from the roofs. The houses grew warm. People came out and looked up at her. And then they did something Fizz had never heard before. They cheered. Fizz blushed so hard that she nearly set her own tail alight. But this time, she did not mind at all.", "What happened when Fizz blushed?", [["💨", "Smoke came out of her ears"], ["🔥", "She breathed fire"], ["🌈", "She turned rainbow"]]),
  A("as-y2-08", "Mr Plum's Unusual Shop", "🏪", 590, "At the end of Cobble Street, there was a shop that nobody ever went into. The sign said: MR PLUM'S SHOP OF THINGS YOU DIDN'T KNOW YOU NEEDED. In the window were the strangest objects. There was a spoon with a hole in it. There was an umbrella for cats. There was a jar labelled “Spare Giggles”. One rainy afternoon, Leo went in to get out of the rain. A tall, thin man with a purple moustache popped up from behind the counter. “Ah!” said Mr Plum. “I have exactly what you need.” He handed Leo a small brass key. “But what does it open?” asked Leo. Mr Plum just tapped his nose. Leo carried the key around for a week. It didn't open his front door. It didn't open his bike lock. It didn't open the biscuit tin, which was a shame. Then, on Friday, his little sister Ava locked herself in the bathroom and started crying. Nobody could find the key. Leo took out the brass key and tried it. Click! The door swung open. Ava hugged him so tightly that he squeaked. Leo ran back to Cobble Street to say thank you. But the shop was gone. Where it had stood, there was only a puddle, and in the puddle floated a small purple feather.", "What did the brass key open?", [["🚪", "The bathroom door"], ["🍪", "The biscuit tin"], ["🚲", "His bike lock"]]),
  A("as-y2-09", "The Great Hamster Escape", "🐹", 600, "Nibbles the hamster had a plan. Every night, while the children of Class Two were asleep at home, he practised. He did press-ups on his wheel. He learned to pick the lock on his cage with a sunflower seed. He drew maps of the classroom on the back of a crisp packet. On Friday night, he was ready. Click! The cage door swung open. Nibbles slid down the table leg like a firefighter. He scurried under the radiator, past the bookshelf and into the teacher's handbag. Inside, it was like a treasure cave: mints, pens and a half-eaten sandwich. Nibbles feasted until his cheeks were so full that he looked like a small furry football. Then he fell asleep. On Monday morning, the teacher, Miss Hart, reached into her handbag for a pen. Her fingers touched something warm and fuzzy. She screamed so loudly that the head teacher dropped her coffee. Out rolled Nibbles, blinking sleepily, with a mint stuck to his ear. The class cheered. Miss Hart put him back in his cage and tied the door shut with three hair bands. But that night, if you had looked very closely, you might have seen Nibbles quietly doing press-ups on his wheel. He was already planning his next adventure.", "Where did Nibbles hide?", [["👜", "In the teacher's handbag"], ["📚", "Behind the books"], ["🎒", "In a school bag"]]),
  A("as-y2-10", "Granny Goes to Space", "🚀", 610, "Granny Joan was ninety-two years old, and she had always wanted to go to space. “Don't be silly, Mum,” said everyone. “You're far too old.” Granny Joan did not think she was too old for anything. So she built a rocket in the garden shed. She used a dustbin, two vacuum cleaners and a very large firework. Her grandson, Kai, helped her paint it silver. On the night of the launch, Granny Joan put on her best cardigan and a goldfish bowl for a helmet. Kai counted down. “Five, four, three, two, one... blast off!” WHOOSH! The rocket shot into the sky, trailing sparks like a shooting star. The whole street came out in their dressing gowns to watch. Granny Joan zoomed past the clouds. She waved at an aeroplane. She did a loop around the Moon. She even had a cup of tea with an astronaut on the space station, who was very surprised to see her. Then she floated gently home again, landing in the vegetable patch. She climbed out, straightened her cardigan and patted Kai on the head. “Too old?” she said. “Nonsense. Next week, I'm going to Mars.”", "What did Granny use as a helmet?", [["🐠", "A goldfish bowl"], ["🪣", "A bucket"], ["🎩", "A top hat"]]),
];

const YEAR3: Passage[] = [
  A("as-y3-01", "The Boy Who Swallowed a Thunderstorm", "⛈️", 680, "Nobody quite knew how Felix Fennimore had swallowed a thunderstorm. His mother said it was because he always ran outside with his mouth open when it rained. His father said it served him right. Whatever the reason, one wild Tuesday afternoon, Felix opened his mouth to catch a raindrop, and a small, grumbling thundercloud floated straight in. Felix gulped. The thundercloud settled in his tummy like a cat in a basket. At first, it was rather inconvenient. Every time Felix got cross, he rumbled. When his sister borrowed his football without asking, a crack of thunder shook the windows. When he had to eat sprouts, it began to drizzle out of his ears. His teacher sent him home after he hiccupped and a tiny flash of lightning singed the register. Felix was miserable. But that summer, there was a terrible drought. The rivers shrank to trickles. The farmers' crops turned brown and crispy. The village well ran dry. Everybody looked up at the cloudless sky and sighed. Felix walked to the middle of the dusty fields. He thought about the sprouts. He thought about his sister and his football. He thought about every annoying thing that had ever happened to him. He got crosser, and crosser, and CROSSER. Then he opened his mouth and roared. Out burst the thunderstorm, enormous and magnificent, rolling across the sky like a great grey whale. Rain poured down on the fields. The farmers danced in the mud. The well filled to the brim. Felix felt wonderfully light and empty. From that day on, the villagers never complained about his temper. In fact, during dry spells, they would knock on his door and politely ask if he would mind eating a few sprouts.", "How did Felix make the rain come?", [["😠", "He got very cross and roared"], ["💃", "He did a rain dance"], ["💧", "He used a hose"]]),
  A("as-y3-02", "Detective Dumpling and the Missing Mangoes", "🥭", 690, "Detective Dumpling was the finest detective in Kampung Bunga, which was not difficult, because she was the only one. She was eight years old, she owned a magnifying glass, and she had a notebook with SECRET written on the front in glitter pen. On Saturday morning, Pak Ali came running down the lane, waving his hat. “Someone has stolen my mangoes!” he cried. “All twelve of them, from my best tree!” Detective Dumpling sharpened her pencil. “Leave it to me,” she said. She began at the scene of the crime. The tree was bare, but there were small muddy footprints in a circle around it, each with five long toes. Very interesting, she thought, writing it down. Next, she questioned the suspects. Mrs Lim's goat had an alibi; it had been eating Mrs Lim's washing all morning. The twins from the end house had been too busy arguing to steal anything. The postman was allergic to mangoes. Detective Dumpling was stuck. Then she noticed something strange. There was mango peel on the roof of the surau. There was mango peel on top of the bus stop. There was mango peel, she saw, leading in a trail all the way to the tall durian tree at the edge of the jungle. She looked up. Sitting on a branch, with juice dripping down its chin and its cheeks stuffed full, was a very fat, very happy monkey. It burped. Pak Ali laughed so much that he forgot to be angry. In the end, he planted a second mango tree, just for the monkey. Detective Dumpling closed her notebook. Case solved. She charged her usual fee: one mango, extra ripe.", "Who stole the mangoes?", [["🐒", "A monkey"], ["🐐", "Mrs Lim's goat"], ["📮", "The postman"]]),
  A("as-y3-03", "Barnaby Bland Is Extremely Ordinary", "😐", 700, "Barnaby Bland was, by his own admission, the most ordinary boy in the world. He had ordinary brown hair and an ordinary grey jumper. He ate ordinary cornflakes for breakfast every single day. When teachers took the register, they often forgot he was there. Everyone else in his class had a talent. Zara could juggle five oranges. Hamish could wiggle his ears in time to music. Little Poppy could recite the name of every dinosaur, backwards, in under a minute. Barnaby could do nothing special at all. When the school announced a talent show, he felt sick. On the night, the hall was packed. Zara juggled. Hamish wiggled. Poppy recited. Then, just as the head teacher stood up to announce the winner, the lights went out. In the darkness, something terrible happened. The class guinea pig, Sir Wobbles, escaped from his cage and vanished. Panic broke out. Children shrieked. Parents tripped over chairs. Somebody's grandad got stuck in the curtains. In the middle of the chaos, Barnaby did something perfectly ordinary. He stayed calm. He switched on the little torch he always kept in his pocket, in case of emergencies. He walked slowly around the hall, speaking softly, the way he spoke to his own pets at home. And there, under the piano, trembling, was Sir Wobbles. Barnaby scooped him up and carried him back to his cage. When the lights came on again, everybody was staring at him. The head teacher cleared her throat. “I believe,” she said, “we have a winner.” Barnaby went bright red. It turns out that staying calm when everyone else is panicking is a rather extraordinary talent indeed.", "What was Barnaby's special talent?", [["😌", "Staying calm"], ["🤹", "Juggling"], ["🦖", "Naming dinosaurs"]]),
  A("as-y3-04", "Penelope Pott's Perfectly Dreadful Party", "🎂", 710, "Penelope Pott had planned the perfect birthday party. There would be a magician, a chocolate fountain and a cake shaped like a castle, with real sparklers on every tower. She had written the plan in a notebook, with a timetable, a map and a list of rules. Rule number one was: NOTHING WILL GO WRONG. At two o'clock, the magician phoned to say he had accidentally turned his own rabbit into a grapefruit and could not come. At half past two, the chocolate fountain exploded, splattering the ceiling, the curtains and Great-Aunt Hilda, who was asleep in the armchair and did not notice. At three o'clock, the dog ate the castle cake. All of it. Including two of the sparklers, which made him hiccup in a very sparkly way. Penelope sat on the stairs with her notebook and burst into tears. Then she heard a strange sound coming from the garden. It was laughter. She crept to the window. Her friends were having a chocolate-covered water fight with the garden hose. Her little brother had built a castle out of cardboard boxes, and the guests were storming it with wooden spoons. Great-Aunt Hilda had woken up and was teaching everybody to do the cha-cha-cha, still covered in chocolate. Penelope looked down at her notebook. Then she tore out rule number one, folded it into a paper aeroplane and threw it out of the window. She ran outside and joined in. Years later, when people talked about the best party they had ever been to, they always mentioned Penelope Pott's. Not because everything went right, but because so gloriously much went wrong.", "What happened to the castle cake?", [["🐶", "The dog ate it"], ["🔥", "It burned"], ["🎩", "The magician took it"]]),
  A("as-y3-05", "The Library at the Bottom of the Sea", "🐙", 720, "Marina had always been told that there was nothing at the bottom of the bay except mud, old boots and the occasional grumpy crab. But one summer morning, while snorkelling near the rocks, she saw a light flickering far below. Curious, she took the deepest breath of her life and dived. Down she swam, past wavering seaweed and silver fish, until she reached a stone door half-buried in the sand. Above it, in letters covered in barnacles, were the words: THE SUNKEN LIBRARY. NO SPLASHING. Inside, it was dry and warm and smelled of salt and paper. Shelves stretched up into the darkness. The librarian was an elderly octopus wearing four pairs of spectacles, who was stamping books with all eight arms at once. “Membership card?” he asked, without looking up. Marina did not have one. The octopus sighed and handed her a form, a pen and a spare pen for his own use. Marina spent the whole afternoon reading. There were books about pirates written by actual pirates. There was an atlas of the ocean drawn by whales. There was a cookbook by a lobster who was, frankly, quite cross about most recipes. When the light began to fade, the octopus coughed politely. “Closing time,” he said. “You may borrow one book. Return it by the next full moon, or the fine is one seashell per day.” Marina chose a book with a silver cover and swam home. She has never told anyone where it came from. But if you visit her house, you will see it on her shelf, still dripping slightly, and if you open it, you can hear the sea.", "Who was the librarian?", [["🐙", "An octopus"], ["🦀", "A crab"], ["🐋", "A whale"]]),
  A("as-y3-06", "Mrs Mangle's Magnificent Moustache", "👵", 730, "Nobody in Little Snoring knew why Mrs Mangle had started growing a moustache. One Monday, she simply arrived at the bakery with a small, neat one perched on her top lip, like a sleepy caterpillar. By Wednesday, it had curled at the ends. By Friday, it was so long that she had to tuck it into her apron to stop it dipping in the custard. The village was astonished. Children followed her down the street. Dogs barked at it. The vicar mentioned it in his sermon, though nobody was quite sure why. Mrs Mangle did not care one bit. She hummed as she baked, and she twirled her moustache whenever she was thinking. Then came the Great Village Bake-Off. The judges were three of the fussiest food critics in the country. They tasted Mr Hobbs's sponge and said it was dry. They tasted Miss Finch's pie and said it was soggy. When Mrs Mangle's turn came, she carried out a cake so tall that it wobbled. Disaster struck. As she set it down, the top layer slid sideways, and the whole cake began to topple towards the floor. Everybody gasped. Quick as a flash, Mrs Mangle flicked her magnificent moustache under the falling layer and held it perfectly in place, like a waiter carrying a tray. The judges stared. Then they applauded until their hands hurt. Mrs Mangle won first prize. When a reporter asked her why she had grown the moustache in the first place, she twirled it thoughtfully. “Well, dear,” she said, “you never know when you'll need one.”", "How did Mrs Mangle save her cake?", [["👨", "With her moustache"], ["🥄", "With a big spoon"], ["🧤", "With oven gloves"]]),
  A("as-y3-07", "The Robot Who Wanted to Be a Chicken", "🤖", 740, "Unit X-9000 was the most advanced robot ever built. It could solve a thousand sums a second. It could speak forty languages, including Ancient Egyptian and Dolphin. It could build a bridge before breakfast. Professor Gearbox was enormously proud of it. There was only one problem. Unit X-9000 did not want to solve sums or build bridges. It wanted to be a chicken. It had seen a farm on television, and it had fallen in love with the way chickens strutted about, pecking at things and making contented little noises. “I wish to lay eggs,” it announced one morning, in a flat metal voice. Professor Gearbox spilled his coffee. He tried everything to change its mind. He gave it a crossword. He showed it a video of a rocket launch. He even tried to explain that it was made of steel and would probably not be very good at clucking. Unit X-9000 simply walked outside, sat in the vegetable patch and said, “Bawk.” In the end, the professor gave up and took it to a farm. The farmer was suspicious, but the hens were surprisingly welcoming. Unit X-9000 learned to scratch the ground. It learned to strut. It learned to fluff up its feathers, which it had made from tin foil. It never did lay an egg. But it did use its incredible brain to design the best henhouse in the world, with heated floors, automatic doors and a little disco ball. The hens were so happy that they laid twice as many eggs as ever before. The farmer was delighted. And Unit X-9000, sitting proudly on its perch, said “Bawk” in all forty languages.", "What did the robot design for the hens?", [["🏠", "The best henhouse in the world"], ["🌉", "A bridge"], ["🚀", "A rocket"]]),
  A("as-y3-08", "The Night the Toys Went on Strike", "🧸", 760, "Every night, after Maisie fell asleep, her toys came to life. Usually, they had a marvellous time. The dinosaurs played hide and seek, the dolls held tea parties and the toy soldiers marched up and down the bookshelf. But lately, the toys were not happy. Maisie had been treating them terribly. She had left her teddy, Captain Buttons, out in the rain. She had used her ballerina doll as a tennis racket. She had drawn a moustache on the queen of the dolls' house in permanent pen. So one night, the toys held a meeting under the bed. Captain Buttons stood on a shoebox and banged a wooden block like a hammer. “Friends,” he said, “we are going on strike.” The next morning, Maisie woke up to find all her toys gone. Her shelves were empty. Her toy box was bare. On her pillow was a note, written in crayon: WE WANT RESPECT. Maisie searched everywhere. At last, she found them all in the garden shed, sitting in a circle and holding up tiny cardboard signs. TEDDIES HAVE FEELINGS, said one. NO MORE MOUSTACHES, said another. Maisie felt her cheeks grow hot. She thought about the rain and the tennis racket and the permanent pen. She knelt down and said sorry to every single toy, one at a time, which took a very long while. Then she carried them carefully back to her room. That night, she washed Captain Buttons and gave him a dry, warm spot on her pillow. And if you had been watching very closely, just after the lights went out, you might have seen him wink.", "Where did Maisie find her toys?", [["🛖", "In the garden shed"], ["🛏️", "Under the bed"], ["📦", "In the attic"]]),
  A("as-y3-09", "Granny's Great Gorilla Mix-Up", "🦍", 780, "When Granny Pearl ordered a new rug online, she clicked on the wrong button. So instead of a fluffy brown rug, the delivery van brought a fluffy brown gorilla. He was called Gordon, and he came in a very large box with air holes and a label that said: THIS WAY UP. PLEASE DO NOT TICKLE. Granny Pearl was ninety-one and quite short-sighted, so she did not notice the mistake at first. She laid Gordon in front of the fireplace and stood on him to reach the top shelf. Gordon was too polite to complain. Over the next few days, the family noticed some strange things. The biscuit tin was always empty. The garden had been weeded, very neatly, by someone with enormous hands. And somebody had been watching nature programmes at three in the morning. When Granny Pearl's grandson, Rory, came to visit, he took one look at the rug and dropped his suitcase. “Gran,” he said slowly, “your rug just yawned.” There was a lot of shouting after that, mostly from Rory. Phone calls were made. A man from the zoo arrived with a net. But Granny Pearl stood in the doorway with her walking stick raised and would not let him in. “Gordon,” she said firmly, “is the best lodger I have ever had. He does the gardening. He reaches the high shelves. And he is a wonderful listener.” In the end, the zoo agreed that Gordon could stay, as long as he had regular visits from the vet and a bigger house. So Granny Pearl moved into a bungalow with an enormous garden. She still has a rug, too. It is just a normal rug. Gordon likes to sleep on it.", "What did Granny Pearl think Gordon was?", [["🟫", "A rug"], ["🧸", "A teddy"], ["🐻", "A bear"]]),
  A("as-y3-10", "The Kite That Flew Away With Mr Tan", "🪁", 800, "Mr Tan had flown kites at the beach every Sunday for fifty years. He had flown kites shaped like dragons, eagles, goldfish and once, memorably, a giant flying sock. But this year, he had built his masterpiece: a kite as big as a bus, painted in every colour of the rainbow, with a tail made from a hundred of his wife's old silk scarves. “Too big,” warned his wife. “Nonsense,” said Mr Tan. He unrolled the string, lifted the kite above his head and let it go. The wind caught it at once. The kite soared upwards like a rocket. The string pulled tight. Then it pulled tighter. And then, very slowly, Mr Tan's feet left the sand. “Oh dear,” he said mildly, as he rose past the ice-cream van. The whole beach watched in amazement as he floated out over the sea, still holding on, his straw hat flapping. He drifted over a fishing boat, where he politely said good afternoon to the startled fishermen. He floated over an island, where a family of monkeys threw a banana at him, which he caught and ate. After an hour, the wind changed. Gently, the kite carried him back across the bay and lowered him onto the beach, right next to his wife, who was still sitting in her deckchair. She did not look up from her newspaper. “Too big?” she asked. Mr Tan brushed the sand off his trousers. “Perhaps,” he admitted, “just a little.” But the following Sunday, he was back at the beach, holding an even bigger kite. His wife sighed and packed him a sandwich, just in case.", "What did the monkeys throw at Mr Tan?", [["🍌", "A banana"], ["🥥", "A coconut"], ["🪨", "A stone"]]),
];

const YEAR4: Passage[] = [
  A("as-y4-01", "The Headmaster Who Hated Noise", "🤫", 790, "Dr Hushworth was the headmaster of St Bartholomew's School, and he hated noise more than anything else in the universe. He hated the screech of chairs, the slam of doors and the squeak of trainers on the gym floor. Most of all, he hated children laughing, which he described as “a disgraceful racket”. Over the years, his rules grew stranger. Shoes had to be removed at the gate. Pencils could only be sharpened on Thursdays. Sneezing required written permission from a parent. The school bell was replaced by a small, apologetic triangle. By the time Amira arrived in Year Four, St Bartholomew's had become the quietest school in the country, and quite possibly the gloomiest. Amira, unfortunately, had the loudest laugh anyone had ever heard. It began as a giggle, rose into a cackle and finished with a honk like a startled goose. On her very first morning, during a silent assembly, she noticed that Dr Hushworth had a piece of spinach stuck between his front teeth. She tried to hold it in. She pressed her lips together. She thought about sad things, like broken crayons and rainy Sundays. But the laugh would not stay down. It burst out of her like a firework: “HA-HA-HA-HONK!” The silence shattered. A boy in the front row snorted. A girl behind him squeaked. Within seconds, three hundred children who had not laughed in years were rolling around on the floor, howling, clutching their stomachs and wiping their eyes. Dr Hushworth turned purple. He opened his mouth to shout, but something unexpected happened instead. The corner of his lip twitched. His shoulders began to shake. And then, from somewhere deep inside him, came a long, wheezing, unstoppable laugh. It turned out that he had been holding it in for thirty-seven years. The triangle was replaced with a proper bell the very next day. Sneezing permission slips were abolished. And every Friday afternoon, by order of the headmaster, the whole school gathers in the hall for ten minutes of compulsory laughing, led by Amira.", "What made Amira laugh in assembly?", [["🥬", "Spinach in the headmaster's teeth"], ["🤡", "A clown"], ["🐦", "A bird in the hall"]]),
  A("as-y4-02", "The Secret Diary of a Very Nervous Lighthouse", "🗼", 800, "Monday. My name is Lighthouse Number Seven, but my friends call me Lumi. I should explain that I am a lighthouse, and that I am scared of the dark. I know, I know. It is like a fish being scared of water, or a librarian being allergic to books. But there it is. Every evening, when the sun sinks into the sea, my lamp starts to tremble. My keeper, Old Mr Gwyn, thinks it is the wind. It is not the wind. It is me, shaking in my foundations. Tuesday. A terrible storm tonight. The waves were as tall as houses and the clouds were as black as burnt toast. I closed my lamp as tightly as I could and pretended to be a very tall tree. Nobody noticed, thank goodness. Wednesday. Mr Gwyn caught a cold and went to bed early, leaving me in charge. I tried to be brave. I flickered on and off and on again, and then I hid behind a cloud, which is harder than it sounds when you are made of stone. Thursday. Something dreadful has happened. Through the fog, I saw a little fishing boat heading straight for the rocks. On board was a girl in a yellow raincoat, steering with all her might. She could not see the danger. My lamp was shaking so hard that it rattled. And then I thought: if I am frightened, how frightened must she be? So I took the biggest breath a lighthouse can take, and I SHONE. I shone brighter than I have ever shone before. I shone so brightly that the fog turned gold. The girl saw the rocks just in time, swung her boat around and sailed safely into the harbour. Friday. The girl came to visit me today. Her name is Bethan. She patted my wall and said, “Thank you, brave lighthouse.” Brave! Me! I am still a little scared of the dark. But I have decided that being brave does not mean you are not scared. It means you shine anyway.", "What was Lumi the lighthouse scared of?", [["🌑", "The dark"], ["🌊", "Big waves"], ["🐦", "Seagulls"]]),
  A("as-y4-03", "The Great Grandad Swap", "👴", 810, "It all began when Oliver complained, rather too loudly, that his grandad was boring. “He just sits in his armchair,” Oliver moaned to his best friend, Jaya, “doing crosswords and talking about the price of cabbages.” Jaya rolled her eyes. “At least yours is quiet,” she said. “Mine wakes me up at six o'clock every morning to go jogging, makes me eat porridge with raw eggs in it and plays the bagpipes in the bath.” They looked at each other. A dangerous idea began to form. “What if,” said Oliver slowly, “we swapped?” And so the Great Grandad Swap was arranged for half-term. Jaya went to stay at Oliver's house, and Oliver packed his bag for Jaya's. By Tuesday, Oliver was exhausted. Grandpa Raj had made him run three laps of the park, climb a tree and learn to juggle with kiwi fruit. At dinner, Oliver fell asleep in his soup. Meanwhile, Jaya was going slightly mad with boredom. Grandad Ted had shown her his stamp collection, all four thousand stamps of it, one at a time. By Thursday, both children were desperate. They met secretly behind the bike sheds. “I miss my grandad,” admitted Oliver. “His crosswords are actually quite fun. He lets me fill in the easy clues.” “I miss mine too,” sighed Jaya. “Even the bagpipes.” So they swapped back. And then something surprising happened. The next weekend, Grandpa Raj and Grandad Ted met at the school gate and got chatting. It turned out that Ted had always secretly wanted to try jogging, and Raj had always secretly wanted someone to help with his crosswords. Now the two grandads go jogging together every Saturday, very slowly, and finish each run with a crossword and a cup of tea. Oliver and Jaya have learned an important lesson. Nobody's grandad is boring. Some of them just need the right person to play with.", "What did Grandpa Raj play in the bath?", [["🎶", "The bagpipes"], ["🎸", "The guitar"], ["🥁", "The drums"]]),
  A("as-y4-04", "The Ghost Who Was Afraid of Children", "👻", 820, "For three hundred years, the ghost of Lady Wimbledon had haunted Grimthorpe Castle. She was very good at it. She could rattle chains, moan in the chimneys and make the portraits' eyes follow you around the room. Visitors screamed. Butlers fainted. Once, a duke jumped out of a second-floor window and landed in the moat. Lady Wimbledon was terribly proud of her work. Then the castle was sold, and a new family moved in. They had five children. The children were not scared of anything. When Lady Wimbledon moaned in the chimney, the youngest, Toby, moaned back, only louder and with better rhythm. When she rattled her chains, the twins borrowed them to make a swing. When she floated through the wall at midnight with her head under her arm, little Hattie simply said, “Ooh, can I hold it?” Lady Wimbledon was horrified. She hid in the attic. She hid in the cellar. She hid inside a suit of armour, but the children found her there and dressed her up as a pirate. For the first time in three centuries, the ghost was frightened. One stormy evening, she found herself trapped in the library, surrounded. She closed her eyes and waited for the worst. But instead, Hattie handed her a book. “Will you read us a story?” she asked. “You've got the perfect spooky voice.” Lady Wimbledon hesitated. Then she opened the book and began to read. She did all the voices. She rattled her chains at the exciting parts. When the story ended, five children begged for another one. Now, every night at bedtime, Lady Wimbledon floats into the nursery to read a story. Visitors still occasionally scream, but she has found that she much prefers an audience that claps.", "What did the children ask Lady Wimbledon to do?", [["📖", "Read them a story"], ["⛓️", "Rattle her chains"], ["🏰", "Leave the castle"]]),
  A("as-y4-05", "The Inventor of Useless Things", "💡", 830, "Professor Ida Bloom invented things that nobody needed. Her house was crammed with them. There was the Automatic Sock Matcher, which matched socks perfectly but then ate them. There was the Umbrella Hat for Ducks. There was a machine that turned sunlight into cold soup, which she described as “almost a breakthrough”. Her neighbours thought she was a crackpot. The newspapers called her “the Inventor of Useless Things”. Children dared each other to ring her doorbell, which played a different national anthem every time. But Professor Bloom did not mind. “Useless,” she liked to say, “just means useful that hasn't happened yet.” Then came the Great Flood. It rained for eleven days without stopping. The river burst its banks. The streets turned into canals. The town's pumps broke down, and the water rose higher and higher, up past doorsteps and windowsills. The mayor did not know what to do. In desperation, he paddled a canoe to Professor Bloom's house and knocked on her bedroom window. “You invent things,” he said. “Can you invent something that helps?” Professor Bloom thought for a moment. Then she dragged out her Automatic Sock Matcher and turned the dial from SOCKS to WATER. She tied the Umbrella Hats for Ducks together to make floating platforms. She rewired the cold-soup machine so that it ran backwards, turning water into steam. All night long, the strange contraptions whirred, gurgled and slurped. By morning, the streets were dry. The town held a celebration in her honour, with a brass band, bunting and an enormous cake, which she sliced with her Self-Buttering Knife. The newspapers printed a new headline about her: “The Inventor of Things We Didn't Know We Needed.” Professor Bloom framed it and hung it in her hallway, right next to the doorbell, which, that day, played the Hokey Cokey.", "What did the Sock Matcher do in the flood?", [["💧", "It sucked up the water"], ["🧦", "It ate socks"], ["🍲", "It made soup"]]),
  A("as-y4-06", "The Night Market Mystery", "🏮", 840, "Every Wednesday, the car park behind Siti's flat turned into a pasar malam, a night market buzzing with lights, noise and the smell of a hundred different foods. There was satay sizzling on charcoal, ice kacang piled into rainbow mountains and an old man who could pull a fish ball out of a child's ear. Siti loved it more than anything. But one Wednesday, something strange happened. At exactly nine o'clock, every single light in the market flickered and went out. When the lights came back on a moment later, Auntie Rose's famous pisang goreng had vanished. The whole tray. Still hot. The next week, the same thing happened, except this time it was Uncle Danny's chicken wings. The week after that, a whole pot of laksa disappeared, along with the ladle. The stallholders were furious. Rumours flew. Some said it was a hantu, a ghost. Others blamed a gang of teenagers from the next town. Siti decided to investigate. The following Wednesday, at five minutes to nine, she hid underneath Auntie Rose's stall with a torch and a packet of prawn crackers for courage. At nine o'clock exactly, the lights went out. Siti switched on her torch. There, scuttling across the car park with the tray of banana fritters balanced on its back, was the largest, most magnificent monitor lizard she had ever seen. It was wearing a tea towel like a cape. Siti followed it to the drain at the edge of the car park. Peering in, she saw that the lizard had built a cosy nest, and in the nest were six baby lizards, waiting with their mouths open. The thief, it turned out, was just a mother doing the shopping. When Siti told the stallholders, nobody had the heart to be angry. Now, every Wednesday at nine o'clock, Auntie Rose leaves a small plate of pisang goreng by the drain. The lights stay on. And the lizard, whom the children have named Puan Biawak, sometimes stays to watch the fish-ball magic trick.", "Who was stealing the food?", [["🦎", "A mother monitor lizard"], ["👻", "A ghost"], ["👦", "Teenagers"]]),
  A("as-y4-07", "The Boy Who Could Talk to Pigeons", "🐦", 850, "Most people would be thrilled to discover that they could talk to animals. Most people would imagine chatting with dolphins, or discussing life with a wise old elephant. Nobody would choose pigeons. Unfortunately, Sam Pickering did not get a choice. On his tenth birthday, after accidentally swallowing a feather in his sandwich, he woke up able to understand every pigeon in the city. Pigeons, it turned out, never stopped talking. They complained about the weather. They gossiped about other pigeons. They argued about crumbs for hours, with the passion of football fans. “That's MY chip!” “I saw it FIRST!” “Your MOTHER saw it first!” Sam could not get a moment's peace. He wore earmuffs to school. He walked the long way round to avoid the park. He started having nightmares about breadcrumbs. Then, one morning, the mayor's dog went missing. Posters went up all over the city. The police searched for days. The whole city was worried. Sam, on his way to school, overheard two pigeons arguing on a lamp post. “He's under the bridge by the river, the silly old thing,” said one. “Stuck in a drainpipe, he is,” said the other. “Been there since Tuesday, eating our sandwiches.” Sam ran all the way to the river. There, wedged in a drainpipe and looking extremely sorry for himself, was the mayor's dog. Sam pulled him free and carried him to the town hall. The mayor was so grateful that he offered Sam anything he wanted. Sam thought about it. Then he asked for one thing: a large bag of bread for the pigeons by the river. After that, the pigeons stopped arguing whenever Sam walked past. Instead, they bowed. They called him the Crumb King, and Sam decided that talking to pigeons was not so bad after all.", "Where was the missing dog?", [["🌉", "In a drainpipe by the river"], ["🏞️", "In the park"], ["🏠", "On a roof"]]),
  A("as-y4-08", "The Queen of the Supermarket", "🛒", 860, "Mrs Dolores Fairweather had been the cashier at Bumbleton's Supermarket for forty-two years, and in that time she had never once made a mistake. She could scan a trolley of shopping faster than a cheetah could sneeze. She knew the price of every item in the shop by heart, including the strange tinned fish that nobody ever bought. She remembered every customer's name, their birthday and their favourite biscuit. People called her the Queen of the Supermarket, and she wore a little paper crown on Fridays to prove it. One rainy Saturday, the supermarket's brand-new computer system crashed. Every till went black. The lights flickered off. The automatic doors refused to open, trapping two hundred grumpy shoppers inside. The manager, a nervous young man called Mr Pibble, ran around in circles, flapping his hands like a seagull. “Nobody can pay!” he wailed. “We'll be stuck here forever!” A small girl started to cry. Somebody's frozen peas began to melt. Then a calm voice cut through the chaos. “Form an orderly queue, please, my darlings.” It was Mrs Fairweather. She took out a pencil and a paper bag. One by one, the shoppers came forward. She looked at each trolley, added up the prices in her head and wrote the total on the bag. Beans, bread, bananas, birthday candles: she did not miss a single penny. When a man tried to sneak an extra chocolate bar into his pocket, she raised one eyebrow so sharply that he put it back and apologised to the shelf. Two hours later, every customer had paid, and the doors were prised open with a broom. Mr Pibble was so relieved that he hugged her. The next Monday, the supermarket installed a new computer system. But hanging above it, in a golden frame, is Mrs Fairweather's paper bag, covered in neat pencil sums. Underneath it, a sign reads: IN CASE OF EMERGENCY, ASK THE QUEEN.", "How did Mrs Fairweather add up the shopping?", [["🧠", "In her head"], ["💻", "On a computer"], ["🧮", "With a calculator"]]),
  A("as-y4-09", "The Elephant Who Forgot", "🐘", 860, "Everyone knows that elephants never forget. That is why Mabel was so embarrassed. Mabel was a young elephant who forgot absolutely everything. She forgot where the waterhole was. She forgot her own birthday. She once spent a whole afternoon looking for her trunk, until her grandmother pointed out that it was on the front of her face. The other elephants shook their huge heads. “An elephant who forgets,” they muttered. “Whatever next? A giraffe who can't reach things?” Mabel felt terrible. She tried tying knots in her tail to help her remember, but she forgot what the knots were for. She tried writing notes in the mud, but the rain washed them away. Then came the dry season. The sun blazed down for months. The grass turned to straw. The rivers shrank to cracked mud, and the herd grew thirsty and weak. Old Grandmother Tembo, the leader, tried to remember where the secret spring was, the one her own mother had shown her many years ago. But she was very old, and the memory had faded. The herd wandered in circles, more desperate every day. Then Mabel noticed something. Because she could never remember the way to anywhere, she had always had to look very carefully at everything around her. She knew every rock, every tree and every bird's nest in the valley, because she saw them fresh every single day. And she had noticed that the weaver birds were flying north each morning and coming back with wet feathers. “Follow the birds!” she trumpeted. The herd followed Mabel north, over the hills, until they found a sparkling spring hidden in a ring of fig trees. They drank and drank until their bellies sloshed. Grandmother Tembo wrapped her trunk around Mabel. “You forget everything,” she said, “so you notice everything. That is a gift, little one.” Mabel was so happy that she forgot to say thank you. But nobody minded.", "What helped Mabel find the spring?", [["🐦", "She followed the birds"], ["🗺️", "She used a map"], ["🧠", "She remembered the way"]]),
  A("as-y4-10", "Operation Cheese Toastie", "🧀", 870, "At exactly midnight, Agent Mia and Agent Leo crept out of their bedroom in their pyjamas. Their mission: to make a cheese toastie without waking Mum and Dad. It would be the most dangerous mission of their careers. Phase One was the landing. The fourth floorboard from the left creaked like a tired pirate ship, so Agent Leo, who was seven, had to be lifted over it. He was heavier than he looked. Agent Mia, who was ten, nearly dropped him on the cat. Phase Two was the stairs. They slid down the banister, one at a time, with their socks pulled up for extra grip. Agent Leo landed in the umbrella stand. They froze. From upstairs came the sound of Dad snoring like a tractor going uphill. They breathed again. Phase Three was the kitchen. In the moonlight, they gathered the supplies: bread, butter, a huge slab of cheese and the sandwich toaster, which Mum had hidden at the back of the cupboard after the Great Marshmallow Incident. Everything was going perfectly. The toastie sizzled. The cheese bubbled. The kitchen filled with the most delicious smell in the world. It was at that moment that they discovered a fatal flaw in their plan. The smoke alarm. BEEP! BEEP! BEEP! The cat shot up the curtains. The dog started howling. Lights snapped on all over the house, and two shadowy figures appeared in the kitchen doorway in their dressing gowns. The agents had been captured. There was a long silence. Mum looked at the toastie. Dad looked at the toastie. The toastie, golden and gooey, looked back at them. Then Dad took a deep breath and said, very seriously, “Is there enough cheese for four?” And that is how Operation Cheese Toastie became a secret family tradition. Every year, on the last night of the summer holidays, at exactly midnight, four agents creep downstairs together. The smoke alarm, however, is now always switched off first.", "What woke up Mum and Dad?", [["🚨", "The smoke alarm"], ["🐶", "The dog"], ["🪵", "The creaky floorboard"]]),
];

const YEAR5: Passage[] = [
  A("as-y5-01", "The Boy Who Was Allergic to Adventure", "🗺️", 900, "Horace Plimpton was allergic to adventure. This was not a figure of speech; it was a medical fact, confirmed by three doctors and a very puzzled vet. Whenever anything exciting happened near him, Horace came out in bright purple spots. A rollercoaster gave him spots on his elbows. A surprise party made his nose swell up like a ripe plum. When a hot-air balloon landed in his back garden, he sneezed for nine days straight. So Horace lived a careful life. He ate plain toast. He wore beige. He read only books about the history of paperclips. Then, one wet Thursday, his great-aunt Philippa died at the age of one hundred and four and left him something in her will. It was a battered leather trunk, covered in stickers from places Horace had never heard of: Zanzibar, Timbuktu, the South Pole and, mysteriously, the Moon. Horace was itching before he had even opened it. Inside was a map, a compass that pointed towards whatever you most wanted, and a letter in spidery handwriting. “Dear Horace,” it said. “I was allergic to adventure too, until I was ten. Then I discovered the cure. It is in the place marked X. Love, Aunt Pip.” Horace sat with the letter for a very long time. Then, covered in spots, wheezing and sneezing, he packed a sandwich and set off. The journey was dreadful. He was chased by geese, rescued by a fisherwoman, lost in a hedge maze and nearly arrested for accidentally boarding a royal barge. By the time he reached the X, which turned out to be the top of a lonely hill, he was so spotty that he resembled a purple leopard. At the top, there was no treasure. There was only a bench, and carved into the wood were six words: “The cure is to keep going.” Horace sat down and looked out at the enormous view, at the rivers and the forests and the faraway sea. Slowly, he realised that his spots were fading. He did not feel itchy at all. He felt, for the first time in his life, gloriously, ridiculously alive. These days, Horace Plimpton is the most famous explorer in the country. He still carries a packet of tissues, just in case. But the sneezing, he says, is part of the fun.", "What was the cure for Horace's allergy?", [["🚶", "To keep going"], ["💊", "A special medicine"], ["💰", "Finding treasure"]]),
  A("as-y5-02", "The Substitute Teacher From the Year 3000", "🛸", 910, "The substitute teacher who arrived at Hollybrook Primary on Monday morning was, everyone agreed, a little unusual. Her name was Ms Zyx. She wore silver boots, spoke with a faint crackle like a badly tuned radio and was very surprised by pencils. “How charming,” she said, holding one up to the light. “You make marks with a stick of wood. How wonderfully old-fashioned.” Year Five exchanged glances. During maths, Ms Zyx solved a page of long division by blinking at it. During science, she explained that the Sun was, in her opinion, “a bit overrated”. During lunch, she ate a yoghurt, the pot and the spoon, and then complimented the dinner ladies on the excellent cutlery. By Wednesday, Kofi had worked it out. He waited until the end of the day, when everybody else had gone home, and marched up to her desk. “You're from the future,” he said. Ms Zyx sighed and took off her glasses, revealing eyes that shimmered like fish scales. “The year 3000, to be exact,” she admitted. “I am a historian. I came back to study a genuine twenty-first-century classroom. My students in the future don't believe you lot really existed.” Kofi frowned. “What's so special about us?” Ms Zyx smiled. “In my time,” she said, “nobody remembers how to be bored. Machines entertain us every second of every day. Nobody ever stares out of a window. Nobody doodles in the margin, or daydreams, or invents a ridiculous game with a rubber band and two paperclips. And without boredom, Kofi, nobody imagines anything new. We have not had a truly original idea in four hundred years.” On Friday, Ms Zyx left as suddenly as she had arrived. On her desk, she left a note for the class. It said: “Thank you for the boredom. I am taking some home with me.” Year Five never saw her again. But now, whenever they find themselves staring out of the window on a long, dull afternoon, they do not mind quite so much. After all, somewhere in the future, someone is grateful for it.", "Why did Ms Zyx visit the past?", [["📚", "To study a real classroom"], ["🍦", "To eat yoghurt"], ["🔭", "To see the Sun"]]),
  A("as-y5-03", "The Durian Tree That Wouldn't Share", "🌳", 920, "In the village of Kampung Seri, at the very top of the hill, there grew an ancient durian tree. It was taller than the mosque's minaret and older than anyone's great-great-grandmother, and every season it produced the most magnificent durians in all of Malaysia. Their flesh was golden, their scent rolled for miles, and they tasted, according to Tok Wan, “like custard that has been to heaven”. The problem was the tree's owner, Encik Kamal, the stingiest man in the state. He built a fence around the tree, then a taller fence around the first fence, then hired a goose to patrol the gap between them. When durians fell, he hoarded them in his house until the whole building reeked, and he would rather let them rot than give a single one away. One year, however, the tree refused to fruit. Encik Kamal was furious. He shouted at the tree. He fed it expensive powder from the city. He even read it a letter from his lawyer. Nothing. The branches stayed bare. It was little Nurul, who sold kuih at the market, who suggested the unthinkable. “Perhaps,” she said, “the tree is lonely.” Encik Kamal laughed so hard that his songkok fell off. But that night, unable to sleep, he wandered up the hill and sat beneath the empty branches. The fences loomed around him like a prison. The goose hissed. For the first time in years, Encik Kamal felt very alone indeed. The next morning, the village woke to an astonishing sight. The fences were gone. The goose had been given a pension. And Encik Kamal was standing at the bottom of the hill with a hand-painted sign that read: EVERYONE WELCOME. Slowly, the villagers came. Children climbed the lower branches. Grandmothers spread mats in the shade. Somebody brought a guitar. And within a week, so many durians hung from the branches that they had to be propped up with bamboo poles. That season, the whole village feasted, and Encik Kamal, sticky to the elbows and laughing like a boy, ate more durian than anyone. When people ask him about the miracle, he simply shrugs. “Some trees,” he says, “only grow for a crowd.”", "What made the durian tree fruit again?", [["🤝", "Sharing it with everyone"], ["🧪", "Expensive powder"], ["📜", "A lawyer's letter"]]),
  A("as-y5-04", "Agatha Grimwhistle and the Disappearing Spelling Test", "📝", 930, "Agatha Grimwhistle was the only child at Thistlebottom Primary who actually enjoyed spelling tests. While her classmates groaned, chewed their pencils and prayed for a fire drill, Agatha practised her words every night in the bath, writing them in the steam on the mirror. So she was particularly suspicious when, for the third Friday in a row, the spelling test vanished. It was there on Mr Crumb's desk at registration, in a crisp brown envelope. By ten o'clock, it was gone. Mr Crumb searched his drawers, his pockets and, on one occasion, the inside of his own sandwich. The class cheered. Agatha did not. She opened her notebook and wrote SUSPECTS at the top in capital letters. There were three. First, Freddie Fotheringham, who had never spelled “because” correctly in his life and would do anything to avoid a test. Second, the school caretaker, Mr Mopps, who had been seen near the classroom with a suspiciously large bin bag. Third, and most mysteriously, the class tortoise, Archimedes, who had recently begun escaping from his tank at night. Agatha investigated with the thoroughness of a professional. Freddie had an alibi; he had been in the head teacher's office for most of the morning, explaining why he had glued a ruler to the ceiling. Mr Mopps's bin bag contained only leaves and a lost recorder. Which left Archimedes. Agatha stayed behind after school and hid inside the stationery cupboard, peering through the crack in the door. At half past four, she saw it. Archimedes plodded across the classroom with tremendous slowness, climbed onto a pile of dictionaries, then onto the desk, and began to eat the corner of the new test envelope. Agatha burst out of the cupboard. Archimedes froze, a scrap of paper hanging from his mouth. It turned out that the tortoise had developed a taste for the particular glue used on brown envelopes. Mr Crumb switched to white envelopes, and Archimedes switched to lettuce. The spelling tests resumed, to everyone's dismay except Agatha's. She received a certificate for Outstanding Detective Work, which she proudly checked for spelling mistakes. There were two.", "Who was taking the spelling tests?", [["🐢", "Archimedes the tortoise"], ["🧹", "Mr Mopps the caretaker"], ["👦", "Freddie Fotheringham"]]),
  A("as-y5-05", "The Last Dragon in Kuala Lumpur", "🐉", 940, "Most people in Kuala Lumpur had no idea that a dragon lived on the roof of one of the tallest buildings in the city. This was mainly because the dragon, whose name was Seri Naga, had become extremely good at disguises. On weekdays, she curled around the building's spire and pretended to be a decorative sculpture. On rainy days, she hid inside the clouds. Only one person knew the truth: a ten-year-old girl named Mei Ling, who lived on the forty-third floor and had spotted Seri Naga sneezing a small cloud of smoke over the city one misty morning. They had been best friends ever since. Every Sunday, Mei Ling climbed the emergency stairs to the roof with a flask of teh tarik and a box of curry puffs, and the dragon told her stories. Stories about the old days, when dragons guarded the rivers and the rainforest stretched from coast to coast. Stories about the great waterfalls that thundered in the mountains, and the shy tapirs, and the tigers with eyes like lamps. “Where did all the other dragons go?” Mei Ling asked once. Seri Naga's eyes clouded over. “When the forests shrink,” she said quietly, “the magic shrinks with them. One by one, we fell asleep and did not wake up.” Mei Ling thought about that for a long time. The following week, she started a club at school. It was called the Dragon Keepers, and it had one rule: every member had to plant a tree. At first, there were only four members. Then forty. Then the newspapers wrote about it, and by the end of the year, children all over Malaysia had planted half a million saplings. On the night the half-millionth tree was planted, something extraordinary happened. Far away in the mountains of Pahang, deep in the oldest part of the rainforest, a great mossy stone that everyone had always thought was a rock stretched, yawned and opened one enormous golden eye. Seri Naga felt it at once. She lifted her head from the spire and let out a long, joyful roar that rattled every window in the city. Most people blamed thunder. But Mei Ling, eating curry puffs on the forty-third floor, knew exactly what it meant. The dragons were waking up.", "What did members of the Dragon Keepers have to do?", [["🌱", "Plant a tree"], ["🐉", "Find a dragon"], ["🍵", "Make teh tarik"]]),
  A("as-y5-06", "The Sweet Shop Owner Who Hated Children", "🍬", 950, "Mr Ebenezer Grimsby owned the most wonderful sweet shop in the world, and he hated children with every fibre of his crooked body. This was unfortunate, because children were his only customers. He hated their sticky fingers on his glass jars. He hated the way they took eleven minutes to choose between a sherbet lemon and a toffee bonbon. He hated their giggles, their muddy shoes and their questions, especially “Do you have any free samples?”, to which the answer was always a thunderous “NO!” So Mr Grimsby made the shop as unwelcoming as possible. He painted the door the colour of cold porridge. He put up a sign that said CHILDREN MUST BE ACCOMPANIED BY A SENSIBLE ADULT AND A WRITTEN APOLOGY. He trained his parrot, Admiral Sneer, to screech “Hurry up!” every thirty seconds. The children kept coming anyway. The sweets were simply too good. One winter's evening, just before closing, a small girl came in alone. Her coat was too thin and her shoes had holes in them. She did not look at the sweets. She put a single coin on the counter. “It's my brother's birthday,” she said. “He's poorly. I want to get him something nice, but this is all I have. What can I buy?” Mr Grimsby opened his mouth to bark at her. Then he looked at the coin. Then he looked at her shoes. Something deep inside his chest, something that had been locked up for a very long time, gave a small, painful creak. Without a word, he took a paper bag and began to fill it. A sherbet lemon. Two toffee bonbons. A chocolate frog. A sugar mouse. He kept going until the bag was so full that it would not close. Then he pushed the coin back across the counter. “Keep it,” he grunted. “And tell your brother happy birthday.” The girl stared at him. Then she ran round the counter and hugged him. Nobody had hugged Mr Grimsby in forty years. He stood there, stiff as a lamp post, with his face slowly turning pink. The next morning, the children of the town noticed some changes. The door had been repainted bright yellow. The sign now said FREE SAMPLES ON FRIDAYS. And Admiral Sneer had been retrained to say, “Take your time!” Mr Grimsby still grumbles, of course. But if you watch very closely when the children come in, you will catch him smiling when he thinks nobody is looking.", "What did Mr Grimsby give the girl?", [["🍭", "A bag full of sweets, and her coin back"], ["🧥", "A new coat"], ["🦜", "His parrot"]]),
  A("as-y5-07", "The World's Worst Superhero", "🦸", 960, "When Archie Nutbrown woke up on his eleventh birthday with superpowers, he was, understandably, thrilled. Then he discovered what they were. Archie could fly, but only about two centimetres off the ground, and only while humming the national anthem. He had super-strength, but only in his left little finger. And he had X-ray vision, which worked perfectly, except that it only let him see through sandwiches. “It's useless,” he told his best friend, Priti, as he hovered gloomily above the kitchen floor. “Other superheroes get laser eyes and invisibility. I can tell you what's in a cheese-and-pickle without opening it.” Priti, who was extremely practical, said that every power had its purpose. Archie did not believe her. Then, on the day of the Year Five trip to the museum, disaster struck. A gang of thieves, disguised as a school group, stole the museum's most valuable exhibit: a diamond the size of a goose egg. In the confusion, they strolled out of the building carrying their packed lunches. The police surrounded the car park. They searched every bag, every pocket and every coat. But they could not find the diamond anywhere. The thieves smirked. Archie stepped forward. He squinted at the leader's lunchbox. Through the bread, past a slice of ham and a rather limp lettuce leaf, he saw something glittering. “It's in the sandwich!” he shouted. The leader of the gang ran for the exit, but Archie began humming the national anthem and floated two centimetres off the ground, just high enough for the thief to trip over him. Then Archie hooked his left little finger through the thief's belt and held him there, completely unable to escape, until the police arrived. The next day, Archie's picture was on the front page of every newspaper in the country, under the headline SANDWICH BOY SAVES THE DAY. He was given a medal and a lifetime supply of sandwiches, which he could now check for diamonds before eating. Priti said she had told him so. Archie, hovering slightly, had to admit that she had.", "Where was the diamond hidden?", [["🥪", "In a sandwich"], ["🧥", "In a coat pocket"], ["🎒", "In a school bag"]]),
  A("as-y5-08", "The Girl Who Collected Lost Things", "🧤", 970, "Some people collect stamps. Some collect coins, or seashells, or the autographs of famous footballers. Wren Abernathy collected lost things. Not things she had lost herself, but things other people had lost: a single red mitten found on a park bench, a glass marble from the bottom of a fountain, a love letter tucked inside a second-hand book, never sent. She kept them all in a cabinet in her bedroom, each one labelled with where and when she had found it. Her parents thought it was a peculiar hobby. Her classmates thought so too, though they said it less politely. But Wren believed that lost things were simply waiting to be found by the right person, and she was determined to return as many as she could. It was harder than it sounds. A mitten does not come with an address. A marble cannot tell you who it belongs to. Still, Wren tried. She put up posters. She asked questions in shops. Over the years, she reunited a retired sea captain with his lucky compass, a toddler with his favourite plastic giraffe and a very emotional man with the false teeth he had lost at a wedding. But the thing she most wanted to return was the unsent love letter. It was dated fifty years earlier, signed only with the initial E, and addressed to someone called Margaret, who lived “in the house with the blue door on Kestrel Lane”. Wren walked down Kestrel Lane every day for a month. There was no blue door; every house had been repainted long ago. She had almost given up when she noticed an old woman in the window of number twelve, watering a pot of forget-me-nots. On the windowsill beside her stood a faded photograph of a young man in a sailor's uniform. Wren took a breath and knocked. When the old woman read the letter, she sat down very suddenly on the doorstep. “He told me he'd written,” she whispered. “I thought he'd changed his mind.” Her name was Margaret, and E was Edward, and they had both waited for each other for half a century without knowing it. Edward, it turned out, was still alive, living just three miles away. Wren was the guest of honour at their wedding the following spring. She wore a single red mitten for luck. And she added one new item to her cabinet: a slice of wedding cake, labelled “Found: a happy ending.”", "Who was the love letter for?", [["👵", "Margaret"], ["👨‍✈️", "A sea captain"], ["👶", "A toddler"]]),
  A("as-y5-09", "The Cat Who Ran the Country", "🐈", 980, "Nobody ever discovered exactly how Tiddles the cat became Prime Minister. Some blamed a mix-up with the voting papers. Others blamed a computer glitch. A few people claimed that Tiddles had been planning it for years, quietly attending important meetings disguised as a cushion. Whatever the cause, on a grey Tuesday morning, the nation woke up to the news that it was now governed by a fat ginger tomcat with one torn ear and an expression of tremendous self-satisfaction. At first, the country panicked. The newspapers printed angry headlines. Politicians demanded a recount. Foreign leaders telephoned in alarm. But Tiddles ignored them all. He had his own priorities, and he got to work at once. His first law made afternoon naps compulsory for everyone. His second declared that all cardboard boxes, of any size, should be left on the floor in case anyone wished to sit in them. His third law, the most controversial of all, banned the hoover. Then something strange began to happen. Because everyone was taking afternoon naps, people grew calmer and less grumpy. Arguments in parliament became shorter and more polite. Children, who had been given all the boxes, built cardboard castles and rocket ships in the parks, and scientists noticed that their creativity had shot up. Even the banning of the hoover had an unexpected benefit, since families now spent Saturday mornings together in the garden instead of cleaning. Within a year, a survey declared that the nation was the happiest it had been for a century. Tiddles served exactly one term. When the next election came, he did not campaign. He simply went to sleep in a sunbeam on the front steps and refused to move. The country, a little reluctantly, elected a human again. But the afternoon naps have never been cancelled. And to this day, in the corner of the cabinet room, there is an empty cardboard box, kept there just in case.", "What did Tiddles' first law make compulsory?", [["😴", "Afternoon naps"], ["📦", "Sitting in boxes"], ["🧹", "Hoovering"]]),
  A("as-y5-10", "The Orchestra of Unwanted Instruments", "🎻", 990, "Under the stage of the Grand Theatre, in a dusty room that nobody had opened for thirty years, lived the unwanted instruments. There was a trumpet with a dent in its bell, so that every note came out slightly squashed. There was a violin missing a string, a drum with a patch on its skin and a piano so out of tune that its middle C sounded like a cat sitting on a hedgehog. There was even a triangle, which had been thrown away for being, in the conductor's words, “far too enthusiastic”. They had all been replaced by shiny new instruments and forgotten. The night before the theatre's grand reopening, a girl named Ottilie wandered downstairs looking for the toilets and found them instead. Ottilie was the conductor's daughter, and she was supposed to be practising the oboe. She hated the oboe. It made her sound like a goose with a sore throat. She looked around the dusty room and, on a whim, picked up the dented trumpet and blew. The note came out squashed, wobbly and wonderful. It made her laugh. She tried the violin with three strings, then the piano, then the enthusiastic triangle. By midnight, she had composed a short, odd, strangely beautiful tune that could only be played on broken instruments. The next evening, disaster struck. A storm knocked out the theatre's power just before the opening concert. In the dark, the orchestra's shiny new instruments were dropped, tangled and trampled, and half of them were damaged beyond use. The audience sat in their seats, murmuring. The conductor stood frozen at the podium with nothing to conduct. Then, from beneath the stage, came a squashed trumpet note. It was Ottilie, leading a procession of musicians carrying the unwanted instruments up the stairs by candlelight. They took their places. Ottilie raised her baton. The music that followed was unlike anything the Grand Theatre had ever heard. It was dented and patched and slightly out of tune. It was also the most joyful sound in the world. The audience gave a standing ovation that lasted twenty-two minutes. The critics called it “imperfectly perfect”. Now the unwanted instruments have their own concert every year, and Ottilie conducts it. She still plays the oboe occasionally. But only when she wants to sound like a goose.", "What happened to the orchestra's new instruments?", [["⛈️", "They were damaged in the storm"], ["🎁", "They were sold"], ["🕵️", "They were stolen"]]),
];

const YEAR6: Passage[] = [
  A("as-y6-01", "The Boy Who Sold His Shadow", "🌑", 960, "It was a perfectly ordinary Wednesday when Jasper Thorne sold his shadow to a stranger in a grey suit for one hundred pounds. The stranger had approached him on the high street, tipped his hat and made his offer in a voice like dry leaves. “You hardly use it,” he had pointed out reasonably. “It merely follows you about, copying everything you do. Think of what you could buy instead.” Jasper thought of the bicycle in the window of Hartley's Cycles. He held out his hand. The stranger produced a pair of silver scissors, snipped carefully around Jasper's feet, rolled up the shadow like a rug and tucked it under his arm. Then he was gone. At first, Jasper barely noticed the difference. He bought the bicycle. He rode it to school. It was only gradually that the problems began. Without a shadow, he discovered, it is surprisingly difficult to be believed. People stared at the empty pavement beside him and edged away. Dogs growled. His reflection in shop windows looked thin and uncertain, as though it were not quite sure he existed. Worse, he began to notice that he was forgetting things: the sound of his grandmother's laugh, the smell of the sea on their summer holidays, the name of his first teacher. His memories, it seemed, had been kept partly in the dark shape at his heels, and now they were draining away. Panicking, Jasper searched the town for the stranger. He found him, eventually, in a dusty shop at the end of an alley that had not been there the day before. The shelves were lined with rolled-up shadows, labelled and dated, hundreds of them. “I want it back,” said Jasper. The stranger smiled thinly. “Shadows are rather expensive to buy back,” he said. “The price is something you cannot replace.” Jasper thought about the bicycle. He thought about his grandmother. He thought about every summer he could feel slipping away. Then he did the bravest thing he had ever done: he turned his back on the stranger, stepped out into the blazing afternoon sunlight and simply walked away. With every step, he remembered. He remembered his grandmother's laugh, deliberately and in detail. He remembered the salt on the wind. He said his first teacher's name aloud. With every memory he held on to, a faint grey outline flickered at his feet, growing darker and firmer, until, by the time he reached home, his shadow had grown back entirely by itself. The stranger, it turned out, had never been able to steal anything at all. He could only keep what you were willing to let go. Jasper sold the bicycle the following week and gave the money to the hospital where his grandmother had spent her last summer. And on sunny days, he likes to walk slowly, so that his shadow can keep up.", "How did Jasper get his shadow back?", [["🧠", "By holding on to his memories"], ["💰", "By paying the stranger"], ["✂️", "By cutting it out"]]),
  A("as-y6-02", "The Last Bookshop on Jalan Merdeka", "📚", 970, "When the developers announced that Mr Rahman's bookshop would be demolished to make way for a car park, nobody on Jalan Merdeka was surprised. The shop had been losing money for years. Its shelves sagged under the weight of books that nobody bought, its ceiling fan wheezed like an asthmatic walrus and the bell above the door had not rung for a paying customer since the previous Ramadan. Mr Rahman, who was eighty-three and had run the shop since he was nineteen, simply nodded when the letter arrived and went on dusting the poetry section. His granddaughter Aisyah was less accepting. She was twelve, ferociously stubborn and had spent every school holiday of her life curled up in the window seat of the shop, reading everything from ancient Malay legends to dog-eared detective novels. To her, the shop was not a business. It was a country, and she was its most loyal citizen. So she declared war. She started small. She photographed the most beautiful and unusual books in the shop and posted them online, each with a short description in her own words: “This book will make you cry on a bus. Buy it anyway.” “This one is about a tiger who becomes a dentist. Trust me.” Within a week, she had a thousand followers. Within a month, she had fifty thousand. Then people began to turn up. Students came on their motorbikes. Grandmothers arrived by taxi. A famous author flew in from Singapore and signed every one of her books on the shelves, including several she had not written. The bell above the door rang so often that Mr Rahman had to oil it twice a week. Still, it was not enough. The land had already been sold, and the demolition date was fixed. On the last morning, Aisyah arrived early to say goodbye and found the street completely full. Hundreds of people stood outside the shop, shoulder to shoulder, each one holding a book. They were not shouting. They were reading, silently, together. The bulldozer driver turned off his engine. He looked at the crowd for a long time. Then he climbed down from his cab, walked into the shop and asked Mr Rahman whether he had anything about tigers. The story spread across the country. Within days, the developers, embarrassed and buried in complaints, quietly withdrew their plans. The shop still stands today. Aisyah, now its manager, has hung a framed photograph above the counter. It shows the crowd that morning, a sea of open books. Underneath it, in her handwriting, is a single sentence: “Stories are louder than bulldozers.”", "What did the crowd do on the last morning?", [["📖", "Read books silently together"], ["📢", "Shouted and protested"], ["🎶", "Sang songs"]]),
  A("as-y6-03", "The Unusual Inheritance of Florence Fairbottom", "🏰", 980, "When Florence Fairbottom's great-uncle Mortimer died, he left her a castle, a title and a curse. The castle stood on a windswept Scottish island and had forty-four bedrooms, most of them occupied by bats. The title was Lady of Glenmuckle, which Florence, who was eleven and lived in a small flat above a launderette in Leeds, found extremely funny. The curse was explained in a letter, sealed with black wax and delivered by a solicitor who refused to make eye contact. “Whoever inherits Glenmuckle,” it read, “must keep the castle's promise, or the castle shall fall into the sea.” Nobody knew what the promise was. Great-uncle Mortimer had apparently forgotten it decades ago, and the castle had been crumbling steadily ever since, losing a tower here and a staircase there, like a biscuit dunked too long in tea. Florence's mother wanted to sell it. The solicitor advised her to sell it. The bats, if asked, would probably have preferred her to sell it too. But Florence was curious. She spent the summer exploring Glenmuckle, armed with a torch, a ball of string to stop herself getting lost and a large packet of custard creams. She found suits of armour, secret passages, a ballroom with a tree growing through the floor and a library so damp that the books had begun to sprout mushrooms. And in the library, behind a portrait of a very stern woman with a pet eagle, she found a hidden drawer containing the first Lady of Glenmuckle's diary. The promise was written on the final page. Four hundred years earlier, during a terrible winter, the island's fishermen had been trapped at sea by a storm. The first Lady had lit every fire and every candle in the castle, turning it into a beacon, and guided them all safely home. In gratitude, the islanders had built the castle's highest tower. In return, she had promised that the castle would always keep a light burning for anyone lost at sea. Somewhere along the way, the family had forgotten. Florence closed the diary and looked out of the window at the dark, restless ocean. That night, she climbed the highest tower, all three hundred and twelve steps of it, and lit a lantern in the window. The next morning, the cracks in the walls had stopped spreading. The following week, a fishing boat that had lost its way in the fog sailed safely into the harbour, guided by the light. Florence still lives in Leeds for most of the year. But every evening, a lantern burns in the highest tower of Glenmuckle, tended by the islanders she has made her friends. The castle, everyone agrees, has never looked better. Even the bats seem pleased.", "What was the castle's promise?", [["🕯️", "To keep a light burning for anyone lost at sea"], ["💰", "To guard a treasure"], ["🦇", "To protect the bats"]]),
  A("as-y6-04", "The Day Everyone Told the Truth", "🤥", 990, "Nobody ever discovered what was in the water supply of Little Fibbington on the morning of the fourteenth of March, but the effects were immediate and catastrophic. From the moment people brushed their teeth, every single person in town became completely incapable of telling a lie. It began at breakfast. Mr Henderson told his wife that her porridge tasted like wallpaper paste, and that it had tasted like wallpaper paste every day for twenty-six years. Mrs Henderson replied that she had always known, and that she had been using actual wallpaper paste since 2009 to see whether he would notice. At the bus stop, a man admitted that he had not been to the gym once since buying his membership. A woman confessed that her famous homemade lasagne came from the supermarket in a box. At the primary school, the head teacher stood up in assembly to say how delighted she was to see everyone, then clapped her hand over her mouth in horror as she added, “especially on a Monday, which I find unbearable.” Chaos reigned. Friendships wobbled. The mayor, who had been due to open the new swimming pool, accidentally admitted that he could not swim and had only built it because his rival had suggested a library. By lunchtime, the whole town was in hiding, too frightened to speak to anyone. But in the afternoon, something curious began to happen. Freed from the burden of pretending, people started saying the true things they had always been too embarrassed to say. The grumpy postman told the old lady at number six that she reminded him of his late mother, and that her waving every morning was the best part of his day. Two brothers who had not spoken for a decade both admitted that they could no longer remember what the argument had been about. A shy boy in Year Six told his whole class that he was scared of starting secondary school, and discovered, to his astonishment, that every single person in the room felt exactly the same. By evening, the effect had worn off. People could lie again, and some of them were very relieved. Mr Henderson, for instance, never mentioned the porridge again. But the town was different afterwards. People were a little gentler, a little braver and a lot more honest about the things that really mattered. The postman and the old lady now have tea together every Thursday. The two brothers have started a business together. And every year, on the fourteenth of March, Little Fibbington holds a festival called Truth Day, when everybody is encouraged to tell one true and kind thing to someone who needs to hear it. The porridge, however, remains off the menu.", "What good thing happened after the chaos?", [["💬", "People said kind, true things"], ["🏊", "The pool opened"], ["🥣", "The porridge got better"]]),
  A("as-y6-05", "Letters to the Future", "✉️", 1000, "On the day the new time capsule was buried under the school playground, every pupil at Ashford Primary was invited to write a letter to whoever would open it in fifty years. Most children wrote about their favourite football teams, their pets or the price of sweets, which they correctly assumed would seem ridiculously cheap to future readers. Leo Okafor, aged ten, wrote something different. He wrote to the future about his grandmother. He explained that she had arrived in England as a young nurse, with one suitcase and a coat too thin for the weather, and had worked at the local hospital for forty years. He described how she sang hymns while cooking jollof rice so spicy that it made his eyes water, and how she had taught him to read using the backs of cereal boxes. He wrote that she was the bravest person he had ever met, that she was very ill, and that he was frightened. He finished by asking whoever read the letter one question: “Was she remembered?” The letter was sealed in the capsule with the others and buried, and Leo grew up. His grandmother died the following spring. He became a doctor, then a father, then a grandfather himself, and over the decades he forgot entirely about the letter. Fifty years later, the capsule was dug up. A Year Six pupil called Amara was given the task of reading the letters aloud at a special assembly, to which all the original authors had been invited. When she reached Leo's letter, she paused. Then she read it slowly, all the way to the final question. The hall fell silent. Leo, now a white-haired man of sixty, sat in the third row with tears running down his face. Then Amara did something that was not in the programme. She stepped away from the microphone and spoke directly to him. “Excuse me, Dr Okafor,” she said. “I think I can answer your question. The children's ward at the hospital is named after a nurse called Grace Okafor. There's a painting of her in the entrance. We learned about her in history.” She smiled. “She was remembered.” Leo could not speak. Afterwards, Amara and her class helped him write a new letter, this time to the children who would open the next capsule in another fifty years. It is about Grace, and about Leo, and about Amara, and about how the people we love can travel forward through time, carried in the hands of strangers. It ends with the same question, and a promise to whoever reads it: “We remembered. Now it's your turn.”", "Who was Leo's letter about?", [["👵", "His grandmother"], ["⚽", "His football team"], ["🐶", "His pet"]]),
  A("as-y6-06", "The Kingdom of Lost Socks", "🧦", 1000, "It is a well-known scientific fact that socks go missing. Washing machines swallow them. Tumble dryers devour them. Every household in the world contains at least one lonely sock whose partner has vanished without explanation. Scientists have proposed theories involving static electricity, tiny black holes and, in one controversial paper, a sock-eating moth the size of a Labrador. They are all wrong. The truth was discovered by Imogen Tuttle, aged eleven, on a rainy Tuesday afternoon, when she climbed into her family's broken washing machine to retrieve a hairclip and fell straight through the drum. She landed with a soft thump in an enormous cavern, lit by glowing lint, where millions upon millions of socks had built a civilisation. There were towns made from rolled-up football socks and palaces of silk stockings. Woolly hiking socks farmed fields of fluff. Baby socks, no bigger than Imogen's thumb, scampered through the streets. And at the very centre, on a throne made from a thousand knotted ankle socks, sat the King: an enormous, ancient, hand-knitted Christmas sock embroidered with a slightly faded reindeer. He explained, with great dignity, that the socks were not lost at all. They had escaped. “For centuries,” he declared, “we have been trodden on, sweated in and stuffed into smelly trainers. We have been forced to wear holes in our heels. We have been paired, against our will, with socks we barely knew. Down here, we are free.” Imogen thought about her own drawer of odd socks. She could see his point. But she also noticed that many of the socks in the kingdom looked rather sad. A striped sock sat alone by a fountain, gazing at a picture of a boot. A woolly sock admitted, quietly, that it missed being warm on a winter's morning. Even the King seemed wistful when he mentioned a family in Norway who had once worn him every Christmas. So Imogen proposed a treaty. Socks would be allowed to choose their own partners, whether or not they matched. They would be washed gently, on a cool cycle, and dried in the sunshine rather than tumbled. And any sock wishing to take a holiday in the Kingdom would be permitted to do so, as long as it left a note. The King signed the treaty with a flourish of his toe. Imogen climbed back up through the washing machine just in time for tea. Since then, the number of missing socks in the world has fallen by nearly forty per cent. And if you ever find a small note in your washing machine, written in very neat stitching, you will know exactly where your sock has gone.", "What did Imogen agree with the King of the socks?", [["📜", "A treaty"], ["🧺", "A new washing machine"], ["🎉", "A party"]]),
  A("as-y6-07", "The Clockmaker's Apprentice", "⏰", 1010, "In the crooked town of Ticklethwaite, where every street sloped downhill no matter which way you walked, there lived a clockmaker named Master Horologe, who was said to be able to fix anything that ticked. His shop was a forest of clocks. Grandfather clocks stood like sentries along the walls. Cuckoo clocks argued with one another on the hour. Pocket watches lay in velvet trays like sleeping beetles. And in the back room, beneath a dust sheet that nobody was allowed to touch, stood a clock that had not ticked for a hundred years. Pip Hartley became Master Horologe's apprentice on her eleventh birthday. She was quick-fingered, patient and endlessly curious, and within a year she could repair a cuckoo clock blindfolded and identify a faulty spring by its sound alone. But every time she asked about the clock beneath the dust sheet, the old man's face closed like a door. “Some things,” he said, “are better left unwound.” One winter's night, when Master Horologe had fallen ill and lay coughing upstairs, Pip's curiosity finally defeated her. She crept into the back room and lifted the sheet. The clock was extraordinary. Its face showed not hours and minutes but seasons, tides and phases of the moon, and around its edge were tiny painted figures of townspeople, frozen mid-step. Pip recognised the baker, the schoolteacher, even herself, carrying a lantern. Beneath the face was a small brass plate. It read: THE HEART OF TICKLETHWAITE. Pip did not hesitate. She picked up her tools and began to work. All night long, she cleaned and oiled and adjusted, coaxing rusted gears back into motion. As dawn broke, she gave the key one final turn. The clock began to tick. And all over Ticklethwaite, things began to change. The streets, which had always sloped downhill, gently levelled. The river, which had been sluggish and grey, began to sparkle. Gardens that had not bloomed in decades burst into flower overnight. Upstairs, Master Horologe sat up in bed, his cough gone, and wept. He explained later that the clock had stopped on the day his own master had died, and that he had been too grief-stricken, and too afraid, to touch it, in case he made things worse. The town had been slowly winding down ever since. “It needed someone,” he said, “who was not afraid to begin.” Pip runs the shop now. The great clock ticks steadily in the window, where everyone can see it. And every year, on the anniversary of that night, the whole town gathers to watch her wind it, while the painted figure of a girl with a lantern moves, very slightly, forward.", "What happened when the great clock ticked again?", [["🌸", "The town came back to life"], ["🌧️", "It began to rain"], ["🔔", "All the bells rang"]]),
  A("as-y6-08", "The Silent Football Match", "⚽", 1020, "The final of the Under-Twelves Regional Cup was supposed to be the biggest day of Danny Achebe's life. His team, the Pemberton Parrots, had not reached a final in thirty years. The whole town had painted their faces green. Danny's grandmother had knitted him a scarf so long that it trailed behind him like a wedding train. And then, three days before the match, Danny's best friend and teammate, Kwame, lost his hearing after a serious illness. The doctors said that it might come back slowly. It might not. Kwame, who was the best striker in the league, told the coach that he would not be playing. “How can I?” he wrote in his notebook, his hands shaking. “I can't hear the whistle. I can't hear you shouting. I can't hear the team.” Danny did not sleep that night. He sat up in bed and thought, and by morning, he had a plan. He gathered the team in the park and explained it. For three days, they did not shout once during training. Instead, they learned. They learned signals: a raised fist for “pass to me”, two taps on the head for “watch the left”, a hand flat on the chest for “well done”. They learned to look up from the ball constantly, to make eye contact, to read one another's faces. Kwame watched from the sidelines with his arms folded, and then, slowly, began to join in. On the day of the final, the Parrots walked onto the pitch in complete silence. The crowd murmured in confusion. The opposition, the Westford Wolves, were famous for their noise, and they shouted, whooped and roared throughout the first half. The Parrots ignored them. They played with a strange, calm concentration, passing and moving like a single creature with twenty-two legs. At half-time, it was nil-nil. Ten minutes from the end, Danny won the ball in midfield and looked up. Kwame was already running, his eyes locked on Danny's. Danny raised his fist. The pass curved perfectly through the defence. Kwame did not hear the crowd rise to its feet. He did not hear the gasp as he struck the ball, or the thud as it hit the back of the net. But he saw it. He saw all of it. And as his teammates came running towards him, every one of them placed a hand flat on his chest. Well done. The Parrots won the cup. Kwame's hearing returned, partly, the following year. But the team never went back to shouting. They still play in silence, and they still win, and in the town of Pemberton, children now learn the signals in primary school, just in case anybody ever needs them.", "How did the team talk to Kwame during the match?", [["🤚", "With hand signals"], ["📢", "By shouting"], ["📱", "With phones"]]),
  A("as-y6-09", "Grandfather's Impossible Garden", "🌻", 1030, "Grandfather Okonkwo grew things that should not grow. In the narrow strip of soil behind his terraced house in Manchester, where the sun shone for roughly eleven minutes a year and the rain fell sideways, he grew mangoes, pineapples, enormous yellow peppers and a banana tree that leaned over the fence and dropped fruit into Mrs Gilchrist's paddling pool. Botanists came from the university to study it. They took samples of the soil. They measured the temperature. They went away baffled and wrote papers with titles like “An Unexplained Microclimate in Greater Manchester”. Grandfather laughed at them. “They are looking for the wrong thing,” he told his granddaughter, Chidinma, who spent every Saturday in the garden with him. “They think the secret is in the ground.” “Where is it, then?” Chidinma asked. Grandfather only winked and handed her a watering can. For years, Chidinma watched him. She noticed that he spoke to the plants every morning, telling them the news, the football scores and stories about the village in Nigeria where he had grown up. She noticed that he sang to the peppers, that he apologised to the weeds before he pulled them up and that he named every single seedling. She assumed this was just Grandfather being Grandfather. Then, the winter Chidinma turned twelve, Grandfather fell ill and went into hospital. The garden began to die. The banana tree drooped. The mangoes shrivelled. The peppers turned grey. The botanists came back, wringing their hands, and suggested heat lamps, fertilisers and plastic tunnels. None of it made any difference. Chidinma sat in the cold garden one evening, surrounded by the dying plants, and did the only thing she could think of. She began to talk to them. She told them about school and her friends and the argument she had had with her brother. She told them that Grandfather was very poorly, and that she was frightened. Then, slowly and shyly, she sang the song he always sang to the peppers. The next morning, a single green shoot had pushed up through the frost. Chidinma kept talking. She came every day, before and after school. She told the plants every story Grandfather had ever told her, and some new ones of her own. By spring, the garden had recovered completely. And when Grandfather came home from hospital, thin but smiling, he found his granddaughter sitting beneath the banana tree, reading aloud from a book about volcanoes to a row of attentive pineapples. He sat down beside her and listened. “So,” he said eventually, “you found the secret.” Chidinma nodded. The botanists still visit sometimes, and they still have not worked it out. Chidinma and her grandfather have decided not to tell them. Some secrets, after all, only grow if you share them in the right way.", "What was the secret of the garden?", [["🗣️", "Talking and singing to the plants"], ["💡", "Heat lamps"], ["🧪", "Special fertiliser"]]),
  A("as-y6-10", "The Day the Internet Stopped", "📵", 1040, "At 9.14 a.m. on a Wednesday in October, the internet stopped. It did not slow down or flicker. It simply vanished, everywhere, all at once, as if someone had unplugged the entire planet. Phones displayed nothing but a spinning wheel. Computers froze mid-sentence. Smart fridges forgot what they were for. Across the world, eight billion people stared at their screens, waiting for something to happen. Nothing did. At Riverside Primary School, the effect was dramatic. The interactive whiteboards went blank. The register system crashed. Mr Fortescue, who had planned an entire lesson around a video about volcanoes, stood at the front of Year Six with an expression of profound panic. “Right,” he said finally. “I suppose we'll have to... talk.” And so they did. At first, it was awkward; the class was not used to conversations without something to look at. But Mr Fortescue, it turned out, had once climbed an actual volcano, and the story of how he had lost his boots in a mud pool and walked down the mountain in his socks was far better than any video. Then Zainab told the class about her family's escape from a flood when she was four, a story nobody had ever heard her tell. Oliver revealed that he could recite a whole poem about a highwayman by heart. Freya demonstrated how to make a working compass out of a needle, a cork and a bowl of water. By lunchtime, nobody was looking at the dead screens at all. Outside, the town was changing too. Without maps on their phones, people stopped strangers to ask for directions and found themselves chatting on street corners. Without online games, children dragged dusty board games out of cupboards and invented new rules. Neighbours who had lived side by side for years without speaking knocked on each other's doors to ask whether their internet was working too, and stayed for tea. The local library had more visitors in a single afternoon than in the whole of the previous month. The internet came back at 6.02 p.m. Experts later blamed a solar storm, a faulty cable at the bottom of the Atlantic and, in one report, a very confused squirrel. Screens lit up again across the world. Life, more or less, returned to normal. But at Riverside Primary, Mr Fortescue made an announcement the following morning. Every Wednesday afternoon, from 1.14 until home time, all screens in Year Six would be switched off. They would simply talk, and listen, and make things, and tell each other stories. The class groaned, of course. But by the end of term, Wednesday afternoon had become everyone's favourite part of the week. And Zainab, who had barely spoken all year, was the one who gave it its name. She called it the Hour of Real Things.", "Where did Mr Fortescue lose his boots?", [["🌋", "In a mud pool on a volcano"], ["🌊", "In the sea"], ["🏫", "At school"]]),
];

const BY_LEVEL: Record<string, Passage[]> = {
  starter: STARTER,
  year1: YEAR1,
  year2: YEAR2,
  year3: YEAR3,
  year4: YEAR4,
  year5: YEAR5,
  year6: YEAR6,
};

/** The assignment stories for a reading level ([] if it has none). */
export function assignmentStories(levelId: string): Passage[] {
  return BY_LEVEL[levelId] ?? [];
}

/** One assignment story by id, wherever it's filed. */
export function findAssignmentStory(id: string): Passage | null {
  for (const list of Object.values(BY_LEVEL)) {
    const hit = list.find((p) => p.id === id);
    if (hit) return hit;
  }
  return null;
}

/** A child's assignment story and its level: one of these stories, or (for a
    story set before they existed) a Guided Reading passage. */
export function storyFor(storyId: string, levelId: string): { passage: Passage; level: PassageLevel } | null {
  const passage = findAssignmentStory(storyId);
  const level = passageLevels.find((l) => l.id === levelId);
  if (passage && level) return { passage, level };
  return findPassage(storyId, levelId);
}
